CREATE SEQUENCE IF NOT EXISTS public.logistics_manifest_seq;
CREATE SEQUENCE IF NOT EXISTS public.reconciliation_case_seq START 100000;
CREATE SEQUENCE IF NOT EXISTS public.commercial_action_seq;
CREATE SEQUENCE IF NOT EXISTS public.commercial_transaction_seq;
GRANT USAGE, SELECT ON SEQUENCE public.logistics_manifest_seq, public.reconciliation_case_seq, public.commercial_action_seq, public.commercial_transaction_seq TO authenticated, service_role;
CREATE OR REPLACE FUNCTION public.next_commercial_action_id() RETURNS text LANGUAGE sql VOLATILE SET search_path = public AS $$ SELECT 'YCA-' || to_char(now(), 'YYYY') || '-' || lpad(nextval('public.commercial_action_seq')::text, 6, '0') $$;
CREATE OR REPLACE FUNCTION public.next_commercial_transaction_id() RETURNS text LANGUAGE sql VOLATILE SET search_path = public AS $$ SELECT 'YCT-' || to_char(now(), 'YYYY') || '-' || lpad(nextval('public.commercial_transaction_seq')::text, 6, '0') $$;
