CREATE TABLE IF NOT EXISTS public.ai_answer_ledger ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asked_by uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id) ON DELETE CASCADE, question text NOT NULL, intent text NOT NULL, domains text[] NOT NULL DEFAULT '{}', verdict text NOT NULL CHECK (verdict IN ('answered','qualified','insufficient_data','not_authorised')), gate_failures text[] NOT NULL DEFAULT '{}', data_quality numeric NOT NULL DEFAULT 0 CHECK (data_quality >= 0 AND data_quality <= 100), confidence numeric NOT NULL DEFAULT 0 CHECK (confidence >= 0 AND confidence <= 100), fact_count integer NOT NULL DEFAULT 0, estimate_count integer NOT NULL DEFAULT 0, prediction_count integer NOT NULL DEFAULT 0, recommendation_count integer NOT NULL DEFAULT 0, freshest_at timestamptz, latency_ms integer, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.ai_security_ledger ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), finding_key text NOT NULL UNIQUE, category text NOT NULL, finding_count integer NOT NULL DEFAULT 0, severity text NOT NULL CHECK (severity IN ('CRITICAL','HIGH','MEDIUM','LOW','INFO')), exploitability text NOT NULL CHECK (exploitability IN ('PROVEN','LIKELY','THEORETICAL','NOT_EXPLOITABLE','UNASSESSED')), tenant_impact boolean NOT NULL DEFAULT false, financial_impact boolean NOT NULL DEFAULT false, authentication_impact boolean NOT NULL DEFAULT false, authorization_impact boolean NOT NULL DEFAULT false, rls_impact boolean NOT NULL DEFAULT false, secret_exposure boolean NOT NULL DEFAULT false, production_blocker boolean NOT NULL DEFAULT false, remediation_status text NOT NULL DEFAULT 'OPEN' CHECK (remediation_status IN ('OPEN','IN_PROGRESS','MITIGATED','FIXED','RISK_ACCEPTED')), risk_acceptance_note text, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, recorded_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.ap360_tax_rules ( code text PRIMARY KEY, label text NOT NULL, tax_type text NOT NULL DEFAULT 'vat', rate_pct numeric(6,3) NOT NULL, taxable_status text NOT NULL DEFAULT 'standard', inclusive boolean NOT NULL DEFAULT false, family_codes text[] NOT NULL DEFAULT '{}', geography text NOT NULL DEFAULT 'KE', authority text NOT NULL DEFAULT 'KRA', source text NOT NULL DEFAULT '', effective_from date NOT NULL DEFAULT CURRENT_DATE, effective_to date, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT ap360_tax_rate CHECK (rate_pct >= 0 AND rate_pct <= 100), CONSTRAINT ap360_tax_status CHECK (taxable_status IN ('standard','zero_rated','exempt','out_of_scope')) );

CREATE TABLE IF NOT EXISTS public.charter_corporate_wallets ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, organization_name text NOT NULL, approver_name text, approver_title text, currency text NOT NULL DEFAULT 'KES', balance_kes numeric NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (owner_id, organization_name) );

CREATE TABLE IF NOT EXISTS public.charter_inventory ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category_slug text NOT NULL, name text NOT NULL, spec text NOT NULL DEFAULT '', capacity text NOT NULL DEFAULT '', base_rate numeric NOT NULL CHECK (base_rate >= 0), currency text NOT NULL DEFAULT 'USD', status text NOT NULL DEFAULT 'available' CHECK (status IN ('available','limited','on-request','maintenance','retired')), offer_label text, offer_discount_pct numeric NOT NULL DEFAULT 0 CHECK (offer_discount_pct >= 0 AND offer_discount_pct <= 90), operator_name text, operator_id uuid, home_base text, available_from date, available_to date, active boolean NOT NULL DEFAULT true, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.charter_wallet_finance_alert_settings ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), singleton boolean NOT NULL DEFAULT true UNIQUE, enabled boolean NOT NULL DEFAULT true, email_recipients text[] NOT NULL DEFAULT '{}', webhook_url text, min_severity text NOT NULL DEFAULT 'major', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.charter_wallet_finance_alert_settings ADD COLUMN IF NOT EXISTS max_attempts integer NOT NULL DEFAULT 6, ADD COLUMN IF NOT EXISTS backoff_base_seconds integer NOT NULL DEFAULT 60, ADD COLUMN IF NOT EXISTS backoff_max_seconds integer NOT NULL DEFAULT 3600;
CREATE TABLE IF NOT EXISTS public.charter_wallet_reconciliation_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), window_start timestamptz NOT NULL, window_end timestamptz NOT NULL, wallets_scanned integer NOT NULL DEFAULT 0, requests_scanned integer NOT NULL DEFAULT 0, findings integer NOT NULL DEFAULT 0, critical integer NOT NULL DEFAULT 0, balanced boolean NOT NULL DEFAULT true, triggered_by text NOT NULL DEFAULT 'cron', created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.commercial_actions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), action_ref text NOT NULL UNIQUE DEFAULT public.next_commercial_action_id(), title text NOT NULL, signal_kind text NOT NULL, signal_evidence jsonb NOT NULL DEFAULT '{}'::jsonb, recommendation text NOT NULL, risk_class text NOT NULL DEFAULT 'low', authority_class text NOT NULL DEFAULT 'A0', approval_required boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'proposed', owner_user_id uuid, owner_label text, expected_revenue_cents bigint, expected_contribution_cents bigint, expected_conversion_pct numeric, confidence_pct numeric, provenance text NOT NULL DEFAULT 'MODELLED', customer_ref text, opportunity_ref text, quote_id uuid, booking_id uuid, booking_table text, dispatch_request_id uuid, invoice_id uuid, payment_id uuid, settlement_id uuid, revenue_event_id uuid, lineage jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid, approved_by uuid, approved_at timestamptz, executed_at timestamptz, closed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT commercial_actions_risk_class_check CHECK (risk_class IN ('low','medium','high','consequential')), CONSTRAINT commercial_actions_authority_check CHECK (authority_class IN ('A0','A1','A2','A3','A4','A5')), CONSTRAINT commercial_actions_status_check CHECK (status IN ('proposed','awaiting_approval','approved','rejected','executing','executed','measured','closed','rolled_back')), CONSTRAINT commercial_actions_provenance_check CHECK (provenance IN ('LIVE','MODELLED','SIMULATED','SEEDED','INCOMPLETE')) );

CREATE TABLE IF NOT EXISTS public.commercial_opportunities ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), opportunity_ref text NOT NULL UNIQUE, stage text NOT NULL DEFAULT 'lead', title text NOT NULL, customer_kind text NOT NULL DEFAULT 'corporate', corporate_id uuid, customer_user_id uuid, customer_label text, source text NOT NULL DEFAULT 'inbound', source_ref text, expected_value_cents bigint, currency text NOT NULL DEFAULT 'KES', probability_pct numeric, quote_id uuid, owner_user_id uuid, lost_reason text, provenance text NOT NULL DEFAULT 'LIVE', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT commercial_opportunities_stage_check CHECK (stage = ANY (ARRAY['lead','qualified','opportunity','quoted','offered','accepted','won','lost'])), CONSTRAINT commercial_opportunities_customer_kind_check CHECK (customer_kind = ANY (ARRAY['corporate','individual','partner','government'])), CONSTRAINT commercial_opportunities_provenance_check CHECK (provenance = ANY (ARRAY['LIVE','MODELLED','SIMULATED','SEEDED','INCOMPLETE'])) );

CREATE TABLE IF NOT EXISTS public.corporate_accounts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legal_name text NOT NULL, trading_name text, kra_pin text NOT NULL, registration_number text, billing_email text NOT NULL, billing_phone text, billing_address text, payment_terms_days integer NOT NULL DEFAULT 30, credit_limit_cents bigint NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'KES', status public.corporate_status NOT NULL DEFAULT 'ACTIVE', metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (kra_pin) );
ALTER TABLE public.corporate_accounts ADD COLUMN IF NOT EXISTS paybill_reference text;
CREATE TABLE IF NOT EXISTS public.corporate_cash_ledger_audit ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, corporate_id UUID NOT NULL, event_type TEXT NOT NULL, ledger_entry_id UUID, proof_id UUID, amount_cents BIGINT, balance_after_cents BIGINT, reference TEXT, paybill_reference TEXT, actor_user_id UUID, actor_email TEXT, notes TEXT, payload JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.corporate_payment_decisions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL, requested_mode public.yalla_payment_mode NOT NULL, decision public.payment_decision_type NOT NULL, requested_amount_cents bigint NOT NULL, available_credit_cents bigint, guarantee_id uuid, facility_id uuid, policy_id uuid, policy_version integer, reason_codes text[] NOT NULL DEFAULT '{}', detail jsonb NOT NULL DEFAULT '{}'::jsonb, actor_id uuid, correlation_id uuid, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.currencies ( code text PRIMARY KEY, name text NOT NULL, symbol text, decimals int NOT NULL DEFAULT 2, is_base boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.delivery_orders ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_number text NOT NULL UNIQUE DEFAULT 'ORD-' || upper(substring(replace(gen_random_uuid()::text,'-',''),1,10)), module text NOT NULL, customer_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, pickup_address text NOT NULL, pickup_lat numeric(10,7), pickup_lng numeric(10,7), pickup_contact_name text, pickup_contact_phone text, pickup_window_start timestamptz, pickup_window_end timestamptz, status text NOT NULL DEFAULT 'draft', total_amount numeric(12,2), currency text NOT NULL DEFAULT 'KES', payment_status text NOT NULL DEFAULT 'unpaid', sla_deadline timestamptz, notes text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.driver_applications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_reference text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'SUBMITTED' CHECK (status IN ('SUBMITTED','UNDER_REVIEW','INFO_REQUESTED','APPROVED','REJECTED','WITHDRAWN')), first_name text NOT NULL, middle_name text, last_name text NOT NULL, gender text, date_of_birth date, national_id text NOT NULL, kra_pin text, contact_email text NOT NULL, contact_phone text NOT NULL, county text, town text, country text NOT NULL DEFAULT 'KE', driver_type text NOT NULL DEFAULT 'individual', licence_number text NOT NULL, licence_classes text[] NOT NULL DEFAULT '{}', licence_expiry date, psv_badge_number text, years_experience integer, vehicle_ownership text NOT NULL DEFAULT 'NONE' CHECK (vehicle_ownership IN ('NONE','OWNER','FLEET_ASSIGNED')), vehicle_registration text, vehicle_make_model text, service_categories text[] NOT NULL DEFAULT '{}', preferred_city text, notes text, applicant_user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, claim_token text NOT NULL, review_notes text, reviewed_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, reviewed_at timestamptz, decided_at timestamptz, driver_id uuid, carrier_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.driver_payout_batches ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_number text NOT NULL UNIQUE, provider text NOT NULL, scheduled_for timestamptz NOT NULL DEFAULT now(), total_count int NOT NULL DEFAULT 0, total_amount_cents bigint NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'KES', status public.driver_payout_batch_status NOT NULL DEFAULT 'OPEN', provider_batch_ref text, submitted_at timestamptz, settled_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.driver_payout_methods ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, method_type public.driver_payout_method_type NOT NULL, msisdn text, bank_code text, bank_account text, account_name text, verified boolean NOT NULL DEFAULT false, is_default boolean NOT NULL DEFAULT false, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.driver_tax_elections ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, regime public.driver_tax_regime NOT NULL, effective_from date NOT NULL, effective_to date, elected_at timestamptz NOT NULL DEFAULT now(), elected_by uuid, document_ref text, notes text, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.driver_tax_profiles ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE, kra_pin text NOT NULL, current_regime public.driver_tax_regime NOT NULL DEFAULT 'TOT', vat_registered boolean NOT NULL DEFAULT false, vat_number text, annual_turnover_cents bigint NOT NULL DEFAULT 0, status public.driver_tax_profile_status NOT NULL DEFAULT 'PENDING', registered_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.driver_tax_reports ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL, period_start date NOT NULL, period_end date NOT NULL, gross_cents bigint NOT NULL DEFAULT 0, taxable_cents bigint NOT NULL DEFAULT 0, tax_cents bigint NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'KES', status text NOT NULL DEFAULT 'DRAFT', metadata jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.driver_tax_returns ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, scheme_code text NOT NULL, period_start date NOT NULL, period_end date NOT NULL, regime public.driver_tax_regime NOT NULL, gross_cents bigint NOT NULL DEFAULT 0, taxable_cents bigint NOT NULL DEFAULT 0, tax_due_cents bigint NOT NULL DEFAULT 0, status public.driver_tax_return_status NOT NULL DEFAULT 'DRAFT', filed_at timestamptz, acknowledgement_ref text, payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (driver_id, scheme_code, period_start, period_end) );

CREATE TABLE IF NOT EXISTS public.etims_invoices ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_number text NOT NULL UNIQUE, kra_invoice_number text UNIQUE, kra_control_unit_id text, kra_signature text, qr_code_payload text, invoice_type public.etims_invoice_type NOT NULL DEFAULT 'SALE', status public.etims_invoice_status NOT NULL DEFAULT 'PENDING', revenue_event_id uuid, transaction_id uuid, journal_id uuid, customer_user_id uuid, customer_name text NOT NULL, customer_kra_pin text, customer_email text, customer_phone text, subtotal_cents bigint NOT NULL CHECK (subtotal_cents >= 0), tax_total_cents bigint NOT NULL DEFAULT 0 CHECK (tax_total_cents >= 0), total_cents bigint NOT NULL CHECK (total_cents >= 0), currency text NOT NULL DEFAULT 'KES', references_invoice_id uuid REFERENCES public.etims_invoices(id), issued_at timestamptz NOT NULL DEFAULT now(), synced_at timestamptz, voided_at timestamptz, voided_reason text, last_error text, retry_count int NOT NULL DEFAULT 0, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.fact_payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL, trip_id uuid, rider_id uuid, driver_id uuid, amount_cents bigint NOT NULL, currency text NOT NULL DEFAULT 'KES', status text, payment_method text, paid_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE IF NOT EXISTS public.fin_ledger_entries ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entry_group uuid NOT NULL, kind public.fin_ledger_entry_kind NOT NULL, account_code text NOT NULL, account_name text NOT NULL, debit_cents bigint NOT NULL DEFAULT 0 CHECK (debit_cents >= 0), credit_cents bigint NOT NULL DEFAULT 0 CHECK (credit_cents >= 0), currency text NOT NULL DEFAULT 'KES', corporate_id uuid, intent_id uuid, reference text, memo text, correlation_id uuid, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), CHECK ((debit_cents = 0) <> (credit_cents = 0)) );

CREATE TABLE IF NOT EXISTS public.finance_change_audit ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_kind text NOT NULL, entity_key text NOT NULL, entity_id uuid, operation text NOT NULL, field text NOT NULL, field_class text NOT NULL, value_before text, value_after text, snapshot_before jsonb, snapshot_after jsonb, changed_by uuid, changed_by_email text, change_source text NOT NULL DEFAULT 'app', reason text, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT fca_entity_kind_check CHECK (entity_kind IN ('service_line_financial_terms','revenue_recognition_rules','commercial_transactions','city_pricing_rules')), CONSTRAINT fca_operation_check CHECK (operation IN ('INSERT','UPDATE','DELETE')), CONSTRAINT fca_field_class_check CHECK (field_class IN ('currency','tax','commission','partner_entitlement','recognition_rule','review','other')) );

CREATE TABLE IF NOT EXISTS public.finance_distribution_lists ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), department TEXT NOT NULL, email TEXT NOT NULL, role TEXT, severity_threshold TEXT NOT NULL DEFAULT 'LOW' CHECK (severity_threshold IN ('LOW','MEDIUM','HIGH','CRITICAL')), active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (department, email) );

CREATE TABLE IF NOT EXISTS public.freight_quotes ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), quote_reference text NOT NULL UNIQUE, version integer NOT NULL DEFAULT 1, status public.freight_quote_status NOT NULL DEFAULT 'DRAFT', owner_user_id uuid, corporate_account_id uuid, order_id uuid, requirement_id uuid, offering_code text NOT NULL, rate_card_id uuid, rate_plan_version integer, snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, quoted_amount numeric(14,2) NOT NULL DEFAULT 0, tax_amount numeric(14,2) NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'KES', valid_from timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT (now() + interval '7 days'), accepted_at timestamptz, accepted_by uuid, superseded_by_quote_id uuid REFERENCES public.freight_quotes(id), correlation_id uuid NOT NULL DEFAULT gen_random_uuid(), idempotency_key text UNIQUE, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.freight_tender_policies ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), policy_code text NOT NULL UNIQUE, policy_label text NOT NULL, active boolean NOT NULL DEFAULT false, min_responses_to_award integer NOT NULL DEFAULT 1 CHECK (min_responses_to_award >= 1), require_compliance_pass boolean NOT NULL DEFAULT true, allow_lowest_price_only boolean NOT NULL DEFAULT false, weight_price numeric(5,2) NOT NULL DEFAULT 40 CHECK (weight_price >= 0), weight_transit numeric(5,2) NOT NULL DEFAULT 15 CHECK (weight_transit >= 0), weight_capacity numeric(5,2) NOT NULL DEFAULT 10 CHECK (weight_capacity >= 0), weight_performance numeric(5,2) NOT NULL DEFAULT 20 CHECK (weight_performance >= 0), weight_compliance numeric(5,2) NOT NULL DEFAULT 15 CHECK (weight_compliance >= 0), max_award_variance_pct numeric(6,2) NOT NULL DEFAULT 0, require_four_eyes_above numeric(14,2), created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (weight_price + weight_transit + weight_capacity + weight_performance + weight_compliance = 100) );

CREATE TABLE IF NOT EXISTS public.journals ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source public.journal_source NOT NULL DEFAULT 'OTHER', reference text, description text, status public.journal_status NOT NULL DEFAULT 'DRAFT', posted_at timestamptz, posted_by uuid, reverses_journal_id uuid REFERENCES public.journals(id), created_by uuid, created_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.journals ADD COLUMN IF NOT EXISTS batch_id uuid;
ALTER TABLE public.journals ADD COLUMN IF NOT EXISTS reversal_reason text;
CREATE TABLE IF NOT EXISTS public.ledger_accounts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, kind public.ledger_account_kind NOT NULL, currency text NOT NULL DEFAULT 'KES', wallet_id uuid REFERENCES public.wallets(id) ON DELETE RESTRICT, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT ledger_accounts_currency_chk CHECK (currency IN ('KES','USD','EUR')) );
ALTER TABLE public.ledger_accounts ADD COLUMN IF NOT EXISTS coa_code text;
ALTER TABLE public.ledger_accounts ADD COLUMN IF NOT EXISTS metadata jsonb NOT NULL DEFAULT '{}'::jsonb;
CREATE TABLE IF NOT EXISTS public.logistics_enquiries ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference text NOT NULL UNIQUE DEFAULT 'ENQ-' || to_char(now(), 'YYMM') || '-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6)), offering_code text NOT NULL, service_label text, contact_name text NOT NULL, contact_email text NOT NULL, contact_phone text, company_name text, contact_user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, origin_label text NOT NULL, destination_label text NOT NULL, cargo_description text NOT NULL, goods_code text, weight_kg numeric(12,2), volume_cbm numeric(12,2), shipment_frequency text NOT NULL DEFAULT 'ONE_OFF', target_date date, budget_amount numeric(14,2), currency text NOT NULL DEFAULT 'KES', requirements text, source_page text, spam_score integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'received', owner_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, respond_by timestamptz NOT NULL DEFAULT now() + interval '1 day', acknowledged_at timestamptz, closed_at timestamptz, outcome text, triage_notes text, is_test boolean NOT NULL DEFAULT false, status_changed_at timestamptz NOT NULL DEFAULT now(), status_changed_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT logistics_enquiries_status_chk CHECK ( status IN ('received','acknowledged','qualifying','quoted','won','lost','closed','spam') ), CONSTRAINT logistics_enquiries_frequency_chk CHECK ( shipment_frequency IN ('ONE_OFF','WEEKLY','MONTHLY','CONTRACT') ), CONSTRAINT logistics_enquiries_weight_chk CHECK (weight_kg IS NULL OR weight_kg > 0), CONSTRAINT logistics_enquiries_volume_chk CHECK (volume_cbm IS NULL OR volume_cbm > 0) );

CREATE TABLE IF NOT EXISTS public.logistics_hubs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, hub_type text NOT NULL DEFAULT 'depot' CHECK (hub_type IN ('depot','warehouse','cross_dock','locker','partner_site')), city text, address text, lat numeric, lng numeric, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.logistics_hubs ADD COLUMN IF NOT EXISTS region text, ADD COLUMN IF NOT EXISTS country_code text NOT NULL DEFAULT 'KE', ADD COLUMN IF NOT EXISTS service_area jsonb NOT NULL DEFAULT '[]'::jsonb, ADD COLUMN IF NOT EXISTS operating_hours jsonb NOT NULL DEFAULT '{}'::jsonb, ADD COLUMN IF NOT EXISTS capabilities text[] NOT NULL DEFAULT '{}'::text[], ADD COLUMN IF NOT EXISTS capacity jsonb NOT NULL DEFAULT '{}'::jsonb, ADD COLUMN IF NOT EXISTS contact_name text, ADD COLUMN IF NOT EXISTS contact_phone text, ADD COLUMN IF NOT EXISTS contact_email text, ADD COLUMN IF NOT EXISTS responsible_operator_id uuid, ADD COLUMN IF NOT EXISTS notes text, ADD COLUMN IF NOT EXISTS created_by uuid;
ALTER TABLE public.logistics_hubs ADD COLUMN IF NOT EXISTS status text NOT NULL DEFAULT 'draft', ADD COLUMN IF NOT EXISTS timezone text NOT NULL DEFAULT 'Africa/Nairobi', ADD COLUMN IF NOT EXISTS capacity_unit text NOT NULL DEFAULT 'parcels', ADD COLUMN IF NOT EXISTS max_capacity numeric, ADD COLUMN IF NOT EXISTS current_capacity numeric NOT NULL DEFAULT 0;
ALTER TABLE public.logistics_hubs ADD COLUMN IF NOT EXISTS dock_count integer NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS storage_capacity_cbm numeric, ADD COLUMN IF NOT EXISTS handling_capacity_units_per_day integer, ADD COLUMN IF NOT EXISTS max_weight_capacity_kg numeric, ADD COLUMN IF NOT EXISTS activated_at timestamptz, ADD COLUMN IF NOT EXISTS activated_by uuid, ADD COLUMN IF NOT EXISTS activation_reason text;
CREATE TABLE IF NOT EXISTS public.mpesa_export_jobs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requested_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, format text NOT NULL CHECK (format IN ('csv','pdf')), filters jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','processing','done','failed','expired')), row_count integer, file_path text, download_url text, error_message text, started_at timestamptz, completed_at timestamptz, expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.mpesa_idempotency_keys ( idempotency_key text PRIMARY KEY, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, request_hash text NOT NULL, response jsonb, status text NOT NULL DEFAULT 'in_flight' CHECK (status IN ('in_flight','succeeded','failed')), created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, expires_at timestamptz NOT NULL DEFAULT (now() + interval '24 hours') );

CREATE TABLE IF NOT EXISTS public.mpesa_rate_limit_buckets ( shortcode text PRIMARY KEY, tokens double precision NOT NULL DEFAULT 100, capacity integer NOT NULL DEFAULT 100, refill_rate_per_sec integer NOT NULL DEFAULT 80, last_refill_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.mpesa_reconciliation_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, window_minutes integer NOT NULL DEFAULT 60, checked_count integer NOT NULL DEFAULT 0, reconciled_count integer NOT NULL DEFAULT 0, mismatch_count integer NOT NULL DEFAULT 0, still_pending_count integer NOT NULL DEFAULT 0, error_count integer NOT NULL DEFAULT 0, notes jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.mpesa_stk_attempts ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, payment_attempt_id UUID NULL, user_id UUID NULL, idempotency_key TEXT NULL, request_id TEXT NULL, correlation_id TEXT NULL, environment TEXT NOT NULL, shortcode TEXT NULL, phone_masked TEXT NULL, amount_cents INTEGER NULL, account_reference TEXT NULL, attempt_number INTEGER NOT NULL DEFAULT 1, outcome TEXT NOT NULL, http_status INTEGER NULL, daraja_response JSONB NULL, merchant_request_id TEXT NULL, checkout_request_id TEXT NULL, error_code TEXT NULL, error_message TEXT NULL, latency_ms INTEGER NULL, will_retry BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
ALTER TABLE public.mpesa_stk_attempts ADD COLUMN IF NOT EXISTS final_result_code integer, ADD COLUMN IF NOT EXISTS final_result_desc text, ADD COLUMN IF NOT EXISTS final_receipt text, ADD COLUMN IF NOT EXISTS reconciled_at timestamptz, ADD COLUMN IF NOT EXISTS reconciliation_mismatch boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS reconciliation_notes text;
CREATE TABLE IF NOT EXISTS public.payment_attempts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT, wallet_id uuid NOT NULL REFERENCES public.wallets(id) ON DELETE RESTRICT, amount_cents bigint NOT NULL CHECK (amount_cents > 0), currency text NOT NULL DEFAULT 'KES', phone text NOT NULL, provider text NOT NULL DEFAULT 'MPESA', idempotency_key text NOT NULL, account_reference text NOT NULL, merchant_request_id text, checkout_request_id text, state public.payment_state NOT NULL DEFAULT 'INITIATED', wallet_posted boolean NOT NULL DEFAULT false, mpesa_receipt_number text, initiated_at timestamptz NOT NULL DEFAULT now(), accepted_at timestamptz, completed_at timestamptz, failure_reason text, ip_address inet, user_agent text, request_id text, correlation_id text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.payment_attempts ADD COLUMN IF NOT EXISTS receiving_account text;
CREATE TABLE IF NOT EXISTS public.payment_audit_logs ( audit_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id uuid NOT NULL REFERENCES public.mpesa_transactions(id) ON DELETE RESTRICT, event_type public.payment_audit_event NOT NULL, old_value jsonb, new_value jsonb, actor_id uuid, actor_type text NOT NULL DEFAULT 'system', ip_address inet, user_agent text, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_callback_certifications ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), correlation_id TEXT NOT NULL, stage TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', evidence JSONB NOT NULL DEFAULT '{}'::jsonb, duration_ms INTEGER, error TEXT, certified_at TIMESTAMPTZ NOT NULL DEFAULT now(), certification_run_id UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_certification_controls ( code text PRIMARY KEY, control_group text NOT NULL, title text NOT NULL, expectation text NOT NULL, verdict text NOT NULL DEFAULT 'NOT_TESTED' CHECK (verdict IN ('IMPLEMENTED','PARTIALLY_IMPLEMENTED','BLOCKED','NOT_TESTED','EXTERNAL_EVIDENCE_REQUIRED','FAILED')), observation text, environment text, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, last_run_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_certification_regressions ( scenario_key text PRIMARY KEY, pinned_fingerprint jsonb NOT NULL, pinned_at timestamptz NOT NULL DEFAULT now(), pinned_by uuid, last_verified_at timestamptz, last_verify_status text, last_run_id uuid, updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_certification_runs ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, triggered_by UUID REFERENCES auth.users(id), environment TEXT NOT NULL DEFAULT 'sandbox', suite_version TEXT NOT NULL DEFAULT 'slice3.v1', status TEXT NOT NULL DEFAULT 'RUNNING', total_scenarios INT NOT NULL DEFAULT 0, passed_scenarios INT NOT NULL DEFAULT 0, failed_scenarios INT NOT NULL DEFAULT 0, skipped_scenarios INT NOT NULL DEFAULT 0, overall_score NUMERIC(5,2), started_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ, summary JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
ALTER TABLE public.payment_certification_runs ADD COLUMN IF NOT EXISTS deployment_version text, ADD COLUMN IF NOT EXISTS git_revision text, ADD COLUMN IF NOT EXISTS build_timestamp timestamptz;
CREATE TABLE IF NOT EXISTS public.payment_certification_safeguards ( id BOOLEAN PRIMARY KEY DEFAULT TRUE CHECK (id = TRUE), max_concurrent_runs INT NOT NULL DEFAULT 2, max_runs_per_hour INT NOT NULL DEFAULT 12, cooldown_minutes_after_failure INT NOT NULL DEFAULT 15, stale_run_minutes INT NOT NULL DEFAULT 30, exclude_synthetic_from_facts BOOLEAN NOT NULL DEFAULT TRUE, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_by UUID );

CREATE TABLE IF NOT EXISTS public.payment_chaos_scenarios ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), scenario_key TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, fault_category TEXT NOT NULL, description TEXT NOT NULL, max_recovery_ms INTEGER NOT NULL DEFAULT 60000, enabled BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_circuit_breakers ( service text PRIMARY KEY, state text NOT NULL DEFAULT 'CLOSED' CHECK (state IN ('CLOSED','OPEN','HALF_OPEN')), failure_count integer NOT NULL DEFAULT 0, success_count integer NOT NULL DEFAULT 0, window_started_at timestamptz NOT NULL DEFAULT now(), opened_at timestamptz, reopens_at timestamptz, last_error text, updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_confidence_reports ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), generated_at timestamptz NOT NULL DEFAULT now(), window_start timestamptz NOT NULL, window_end timestamptz NOT NULL, confidence_pct numeric(5,2) NOT NULL, can_process_production_money boolean NOT NULL, reasons jsonb NOT NULL DEFAULT '[]'::jsonb, metrics jsonb NOT NULL DEFAULT '{}'::jsonb, signature text, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_config_baseline ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), fingerprint text NOT NULL, surface jsonb NOT NULL DEFAULT '{}'::jsonb, captured_at timestamptz NOT NULL DEFAULT now(), approved_by uuid, is_current boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_config_certifications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ran_at timestamptz NOT NULL DEFAULT now(), fingerprint text NOT NULL, passed boolean NOT NULL, checks jsonb NOT NULL DEFAULT '[]'::jsonb, drift_from_baseline jsonb NOT NULL DEFAULT '{}'::jsonb, failure_reason text, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_continuous_qualification_runs ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), triggered_at TIMESTAMPTZ NOT NULL DEFAULT now(), triggered_by TEXT NOT NULL DEFAULT 'cron', chain_key TEXT NOT NULL DEFAULT 'e2e_14_step', status TEXT NOT NULL DEFAULT 'RUNNING', cert_run_id UUID, total_steps INT, passed_steps INT, failed_steps INT, correlation_ids TEXT[], forensic_bundle JSONB, error TEXT, completed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
ALTER TABLE public.payment_continuous_qualification_runs ADD COLUMN IF NOT EXISTS failure_class TEXT REFERENCES public.payment_qualification_failure_classes(class_key), ADD COLUMN IF NOT EXISTS financial_integrity_score NUMERIC(5,2), ADD COLUMN IF NOT EXISTS reliability_score NUMERIC(5,2), ADD COLUMN IF NOT EXISTS readiness_score NUMERIC(5,2), ADD COLUMN IF NOT EXISTS evidence_pack_id UUID REFERENCES public.payment_qualification_evidence_packs(id), ADD COLUMN IF NOT EXISTS correlation_id TEXT;
CREATE TABLE IF NOT EXISTS public.payment_decision_trees ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), decision_id UUID NOT NULL, tree JSONB NOT NULL, root_verdict TEXT NOT NULL, confidence NUMERIC, recommendations JSONB NOT NULL DEFAULT '[]'::jsonb, historical_comparison JSONB, built_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (decision_id) );

CREATE TABLE IF NOT EXISTS public.payment_disputes ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id uuid REFERENCES public.mpesa_transactions(id), raised_by uuid NOT NULL, corporate_id uuid, reason public.dispute_reason NOT NULL, amount_cents bigint NOT NULL CHECK (amount_cents > 0), currency text NOT NULL DEFAULT 'KES', status public.dispute_status NOT NULL DEFAULT 'OPEN', description text, resolution_notes text, resolved_at timestamptz, resolved_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_events ( event_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id uuid NOT NULL REFERENCES public.mpesa_transactions(id) ON DELETE RESTRICT, event_type public.payment_event_type NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, actor_id uuid, actor_type text NOT NULL DEFAULT 'system', created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_evidence_exports ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), requested_at TIMESTAMPTZ NOT NULL DEFAULT now(), requested_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, identifier_kind TEXT NOT NULL, identifier_value TEXT NOT NULL, correlation_id TEXT, bundle_sha256 TEXT, row_count INT, bundle JSONB NOT NULL DEFAULT '{}'::jsonb, status TEXT NOT NULL DEFAULT 'complete' );
ALTER TABLE public.payment_evidence_exports ADD COLUMN IF NOT EXISTS deployment_version TEXT, ADD COLUMN IF NOT EXISTS git_revision TEXT, ADD COLUMN IF NOT EXISTS schema_version TEXT, ADD COLUMN IF NOT EXISTS rollout_percent NUMERIC, ADD COLUMN IF NOT EXISTS readiness_snapshot JSONB, ADD COLUMN IF NOT EXISTS reliability_score NUMERIC, ADD COLUMN IF NOT EXISTS certification_run_id UUID, ADD COLUMN IF NOT EXISTS evidence_version TEXT NOT NULL DEFAULT 'v2', ADD COLUMN IF NOT EXISTS evidence_signature TEXT;
ALTER TABLE public.payment_evidence_exports ADD COLUMN IF NOT EXISTS package_format TEXT CHECK (package_format IN ('json','pdf','bundle')) DEFAULT 'json', ADD COLUMN IF NOT EXISTS signature_algorithm TEXT, ADD COLUMN IF NOT EXISTS signer_key_id TEXT, ADD COLUMN IF NOT EXISTS signed_manifest JSONB;
ALTER TABLE public.payment_evidence_exports ADD COLUMN IF NOT EXISTS canonical_payload_sha256 text, ADD COLUMN IF NOT EXISTS signature_sha256 text, ADD COLUMN IF NOT EXISTS canonicalization_version text, ADD COLUMN IF NOT EXISTS signing_key_id text, ADD COLUMN IF NOT EXISTS migration_version text, ADD COLUMN IF NOT EXISTS runner_version text, ADD COLUMN IF NOT EXISTS verification_verdict text, ADD COLUMN IF NOT EXISTS verification_last_at timestamptz;
CREATE TABLE IF NOT EXISTS public.payment_evidence_retention_checks ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), evidence_pack_id UUID NOT NULL, checked_at TIMESTAMPTZ NOT NULL DEFAULT now(), hash_ok BOOLEAN NOT NULL, signature_ok BOOLEAN NOT NULL, replay_ok BOOLEAN NOT NULL, drift_details JSONB NOT NULL DEFAULT '{}'::jsonb, correlation_id TEXT );

CREATE TABLE IF NOT EXISTS public.payment_forecast_accuracy ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), metric TEXT NOT NULL, forecast_id UUID, model_version TEXT, window_start TIMESTAMPTZ NOT NULL, window_end TIMESTAMPTZ NOT NULL, predicted_value NUMERIC NOT NULL, actual_value NUMERIC NOT NULL, absolute_error NUMERIC GENERATED ALWAYS AS (abs(actual_value - predicted_value)) STORED, percent_error NUMERIC GENERATED ALWAYS AS ( CASE WHEN actual_value = 0 THEN NULL ELSE abs(actual_value - predicted_value) / abs(actual_value) * 100 END ) STORED, drift_flag BOOLEAN NOT NULL DEFAULT false, notes JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_fraud_cases ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), case_number TEXT NOT NULL UNIQUE DEFAULT ('PF-' || to_char(now(),'YYYYMMDD') || '-' || substr(gen_random_uuid()::text,1,8)), payment_ref UUID, payment_source TEXT, entity_type public.risk_entity_type NOT NULL, entity_id UUID, amount NUMERIC(14,2), currency TEXT DEFAULT 'KES', status public.fraud_review_status NOT NULL DEFAULT 'open', severity public.risk_event_severity NOT NULL DEFAULT 'medium', signals JSONB NOT NULL DEFAULT '[]'::JSONB, assigned_to UUID REFERENCES auth.users(id) ON DELETE SET NULL, resolved_at TIMESTAMPTZ, notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_incident_groups ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), group_key TEXT NOT NULL UNIQUE, root_cause TEXT NOT NULL, severity TEXT NOT NULL DEFAULT 'warn', status TEXT NOT NULL DEFAULT 'OPEN', first_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(), last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(), member_count INT NOT NULL DEFAULT 0, summary JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
ALTER TABLE public.payment_incident_groups ADD COLUMN IF NOT EXISTS drill_down_context JSONB NOT NULL DEFAULT '{}'::jsonb;
CREATE TABLE IF NOT EXISTS public.payment_infra_slos ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slo_key text NOT NULL UNIQUE, display_name text NOT NULL, description text, unit text NOT NULL, direction text NOT NULL DEFAULT 'lower_is_better' CHECK (direction IN ('lower_is_better','higher_is_better')), target_value numeric NOT NULL, warn_value numeric NOT NULL, critical_value numeric NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_journey_events ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), correlation_id UUID NOT NULL, parent_correlation_id UUID, workflow_name TEXT, event_key TEXT NOT NULL, event_status TEXT NOT NULL DEFAULT 'OK' CHECK (event_status IN ('OK','INVOKED','SKIPPED','FAILED','WAITING','RETRIED')), actor TEXT, source_component TEXT, payment_attempt_id UUID, payment_session_id UUID, checkout_request_id TEXT, merchant_request_id TEXT, phone TEXT, wallet_id UUID, ride_id UUID, order_id UUID, latency_ms INTEGER, evidence JSONB NOT NULL DEFAULT '{}', occurred_at TIMESTAMPTZ NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_journey_stages ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), correlation_id UUID NOT NULL, payment_attempt_id UUID, stage_key TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'INVOKED' CHECK (status IN ('INVOKED','OK','SKIPPED','FAILED','WAITING','TIMED_OUT')), latency_ms INTEGER, evidence JSONB NOT NULL DEFAULT '{}', occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(correlation_id, stage_key) );

CREATE TABLE IF NOT EXISTS public.payment_load_qualification_runs ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), concurrency_tier INTEGER NOT NULL CHECK (concurrency_tier IN (100, 250, 500, 1000)), scenario TEXT NOT NULL DEFAULT 'stk_burst', status TEXT NOT NULL DEFAULT 'running' CHECK (status IN ('running','passed','failed','aborted')), started_at TIMESTAMPTZ NOT NULL DEFAULT now(), finished_at TIMESTAMPTZ, total_requests INTEGER NOT NULL DEFAULT 0, successful_requests INTEGER NOT NULL DEFAULT 0, failed_requests INTEGER NOT NULL DEFAULT 0, callback_latency_p50_ms NUMERIC, callback_latency_p95_ms NUMERIC, callback_latency_p99_ms NUMERIC, controller_latency_p95_ms NUMERIC, wallet_posting_latency_p95_ms NUMERIC, ledger_latency_p95_ms NUMERIC, settlement_latency_p95_ms NUMERIC, max_queue_depth INTEGER, max_outbox_lag_ms NUMERIC, error_rate NUMERIC, financial_integrity_score NUMERIC, notes TEXT, created_by UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_manual_overrides ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), operator_user_id uuid NOT NULL REFERENCES auth.users(id), operator_role text NOT NULL, action text NOT NULL CHECK (action IN ('force_promote','force_rollback','pause','resume','kill_switch_on','kill_switch_off')), from_percent numeric, to_percent numeric, justification text NOT NULL, signature text NOT NULL, expires_at timestamptz, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_notification_channels ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, channel_type text NOT NULL CHECK (channel_type IN ('slack','webhook','email')), target text NOT NULL, event_filter text[] NOT NULL DEFAULT ARRAY['*'], min_severity text NOT NULL DEFAULT 'info' CHECK (min_severity IN ('info','warn','critical')), active boolean NOT NULL DEFAULT true, secret_ref text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['ai_answer_ledger','ai_security_ledger','ap360_tax_rules','charter_corporate_wallets','charter_inventory','charter_wallet_finance_alert_settings','charter_wallet_reconciliation_runs','commercial_actions','commercial_opportunities','corporate_accounts','corporate_cash_ledger_audit','corporate_payment_decisions','currencies','delivery_orders','driver_applications','driver_payout_batches','driver_payout_methods','driver_tax_elections','driver_tax_profiles','driver_tax_reports','driver_tax_returns','etims_invoices','fact_payments','fin_ledger_entries','finance_change_audit','finance_distribution_lists','freight_quotes','freight_tender_policies','journals','ledger_accounts','logistics_enquiries','logistics_hubs','mpesa_export_jobs','mpesa_idempotency_keys','mpesa_rate_limit_buckets','mpesa_reconciliation_runs','mpesa_stk_attempts','payment_attempts','payment_audit_logs','payment_callback_certifications','payment_certification_controls','payment_certification_regressions','payment_certification_runs','payment_certification_safeguards','payment_chaos_scenarios','payment_circuit_breakers','payment_confidence_reports','payment_config_baseline','payment_config_certifications','payment_continuous_qualification_runs','payment_decision_trees','payment_disputes','payment_events','payment_evidence_exports','payment_evidence_retention_checks','payment_forecast_accuracy','payment_fraud_cases','payment_incident_groups','payment_infra_slos','payment_journey_events','payment_journey_stages','payment_load_qualification_runs','payment_manual_overrides','payment_notification_channels'] LOOP EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t); EXECUTE format('GRANT ALL ON public.%I TO service_role', t); EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('CREATE POLICY "Admins manage restored records" ON public.%I FOR ALL TO authenticated USING (public.has_any_role(auth.uid(), ARRAY[''admin'',''super_admin'',''finance_admin'']::public.app_role[])) WITH CHECK (public.has_any_role(auth.uid(), ARRAY[''admin'',''super_admin'',''finance_admin'']::public.app_role[]))', t); END LOOP; END $$;CREATE TABLE IF NOT EXISTS public.payment_orchestrator_approvals ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), correlation_id text NOT NULL, rollout_stage int NOT NULL, from_percent numeric NOT NULL, to_percent numeric NOT NULL, approver_user_id uuid REFERENCES auth.users(id), approver_role text, approval_timestamp timestamptz NOT NULL DEFAULT now(), approval_expiration timestamptz NOT NULL, readiness_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, reliability_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, confidence_score numeric, signature text NOT NULL, reason text, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','expired','consumed')), consumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_orchestrator_decisions ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), decided_at TIMESTAMPTZ NOT NULL DEFAULT now(), action TEXT NOT NULL CHECK (action IN ('promote','hold','rollback','no_change')), from_percent INT NOT NULL, to_percent INT NOT NULL, reason TEXT NOT NULL, evidence JSONB NOT NULL DEFAULT '{}'::jsonb, gate_ready BOOLEAN, reliability_score NUMERIC, callback_health TEXT, shadow_equivalence NUMERIC, active_critical_incidents INT NOT NULL DEFAULT 0, correlation_id TEXT );
ALTER TABLE public.payment_orchestrator_decisions ADD COLUMN IF NOT EXISTS confidence_score numeric, ADD COLUMN IF NOT EXISTS confidence_breakdown jsonb DEFAULT '{}'::jsonb, ADD COLUMN IF NOT EXISTS is_dry_run boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS rollback_simulation jsonb, ADD COLUMN IF NOT EXISTS approval_id uuid REFERENCES public.payment_orchestrator_approvals(id), ADD COLUMN IF NOT EXISTS environment text NOT NULL DEFAULT 'production', ADD COLUMN IF NOT EXISTS forecast_evidence jsonb;
CREATE TABLE IF NOT EXISTS public.payment_orchestrator_env_policy ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), environment text NOT NULL UNIQUE CHECK (environment IN ('development','testing','sandbox','production')), approval_mode text NOT NULL DEFAULT 'autonomous' CHECK (approval_mode IN ('autonomous','approval_required','dual_approval','emergency_override')), required_approver_count int NOT NULL DEFAULT 1, approver_roles text[] NOT NULL DEFAULT ARRAY['admin','super_admin'], approval_ttl_minutes int NOT NULL DEFAULT 60, emergency_override_role text NOT NULL DEFAULT 'super_admin', notification_channels text[] NOT NULL DEFAULT ARRAY['slack'], created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_orchestrator_flag ( id boolean PRIMARY KEY DEFAULT true CHECK (id = true), enabled boolean NOT NULL DEFAULT false, shadow_mode boolean NOT NULL DEFAULT true, rollout_percent int NOT NULL DEFAULT 0 CHECK (rollout_percent BETWEEN 0 AND 100), kill_switch boolean NOT NULL DEFAULT false, updated_by uuid, updated_at timestamptz NOT NULL DEFAULT now(), note text );

CREATE TABLE IF NOT EXISTS public.payment_orchestrator_rollout_stages ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), stage_order INT NOT NULL UNIQUE, target_percent INT NOT NULL CHECK (target_percent BETWEEN 0 AND 100), min_dwell_minutes INT NOT NULL DEFAULT 30, min_reliability_score NUMERIC NOT NULL DEFAULT 95, min_shadow_equivalence NUMERIC NOT NULL DEFAULT 99, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_orchestrator_shadow_diffs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), correlation_id text NOT NULL, legacy_outcome jsonb NOT NULL, shadow_outcome jsonb NOT NULL, diff_keys text[] NOT NULL DEFAULT '{}', is_equivalent boolean NOT NULL, legacy_duration_ms int, shadow_duration_ms int, deployment_version text, git_revision text, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_pci_snapshots ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), computed_at timestamptz NOT NULL DEFAULT now(), score numeric(6,2) NOT NULL, per_domain jsonb NOT NULL DEFAULT '{}'::jsonb, streak_days integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_pci_streaks ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), started_at timestamptz NOT NULL DEFAULT now(), current_days integer NOT NULL DEFAULT 0, best_days integer NOT NULL DEFAULT 0, last_score numeric(6,2), last_computed_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_platform_health ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, window_start TIMESTAMPTZ NOT NULL, window_end TIMESTAMPTZ NOT NULL, edge_invocations INT NOT NULL DEFAULT 0, stk_attempts INT NOT NULL DEFAULT 0, stk_success_rate NUMERIC(5,2), callbacks_received INT NOT NULL DEFAULT 0, callback_success_rate NUMERIC(5,2), duplicate_callbacks INT NOT NULL DEFAULT 0, oauth_success_rate NUMERIC(5,2), avg_callback_latency_ms INT, infra_cert_status TEXT, journeys_completed INT NOT NULL DEFAULT 0, journeys_stalled INT NOT NULL DEFAULT 0, active_incidents INT NOT NULL DEFAULT 0, idempotency_violations INT NOT NULL DEFAULT 0, overall_health_score NUMERIC(5,2), breakdown JSONB NOT NULL DEFAULT '{}'::jsonb, computed_at TIMESTAMPTZ NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_projection_registry ( projection_name text PRIMARY KEY, table_name text NOT NULL, sync_fn text NOT NULL, weight numeric NOT NULL DEFAULT 1, enabled boolean NOT NULL DEFAULT true, description text, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_qualification_failure_classes ( class_key TEXT PRIMARY KEY, label TEXT NOT NULL, description TEXT, severity TEXT NOT NULL DEFAULT 'high', created_at TIMESTAMPTZ NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_qualification_reports ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), report_date DATE NOT NULL UNIQUE, build_version TEXT, git_revision TEXT, migration_version TEXT, rolling_windows JSONB NOT NULL DEFAULT '{}'::jsonb, financial_integrity JSONB NOT NULL DEFAULT '{}'::jsonb, reliability JSONB NOT NULL DEFAULT '{}'::jsonb, slo_compliance JSONB NOT NULL DEFAULT '{}'::jsonb, callback_success JSONB NOT NULL DEFAULT '{}'::jsonb, latency_percentiles JSONB NOT NULL DEFAULT '{}'::jsonb, certification_summary JSONB NOT NULL DEFAULT '{}'::jsonb, critical_incident_count INTEGER NOT NULL DEFAULT 0, chaos_summary JSONB NOT NULL DEFAULT '{}'::jsonb, load_summary JSONB NOT NULL DEFAULT '{}'::jsonb, forensics_summary JSONB NOT NULL DEFAULT '{}'::jsonb, retention_summary JSONB NOT NULL DEFAULT '{}'::jsonb, promotion_recommendation TEXT NOT NULL CHECK (promotion_recommendation IN ('eligible','blocked','insufficient_evidence')), promotion_blockers JSONB NOT NULL DEFAULT '[]'::jsonb, canonical_payload_sha256 TEXT NOT NULL, hmac_signature TEXT NOT NULL, signing_key_id TEXT NOT NULL DEFAULT 'PAYMENT_EVIDENCE_SIGNING_KEY', generated_at TIMESTAMPTZ NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_rca_classifications ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), correlation_id UUID NOT NULL, payment_attempt_id UUID, category TEXT NOT NULL, last_successful_stage TEXT, first_failed_stage TEXT, supporting_evidence JSONB NOT NULL DEFAULT '{}', classified_by TEXT NOT NULL DEFAULT 'auto', classified_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(correlation_id, category) );

CREATE TABLE IF NOT EXISTS public.payment_receiving_accounts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL, channel text NOT NULL, account_number text NOT NULL, country text NOT NULL DEFAULT 'KE', currency text NOT NULL DEFAULT 'KES', service text NOT NULL DEFAULT 'all', status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','active','retired')), verification_status text NOT NULL DEFAULT 'unverified' CHECK (verification_status IN ('unverified','verified')), config_version int NOT NULL DEFAULT 1, effective_from date NOT NULL DEFAULT current_date, effective_until date, approved_by uuid, note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_regression_fingerprints ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), fingerprint_key text NOT NULL UNIQUE, workstream text NOT NULL, description text NOT NULL, scenario_key text, test_path text, ci_workflow text, registered_at timestamptz NOT NULL DEFAULT now(), active boolean NOT NULL DEFAULT true );

CREATE TABLE IF NOT EXISTS public.payment_reliability_forecasts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), component text NOT NULL, current_status text, predicted_status text, probability numeric, eta_minutes int, likely_cause text, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, computed_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.payment_reliability_forecasts ADD COLUMN IF NOT EXISTS window_start timestamptz, ADD COLUMN IF NOT EXISTS window_end timestamptz;
CREATE TABLE IF NOT EXISTS public.payment_reliability_snapshots ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), computed_at timestamptz NOT NULL DEFAULT now(), reliability_score numeric(5,2) NOT NULL, callback_score numeric(5,2) NOT NULL, journey_score numeric(5,2) NOT NULL, edge_function_score numeric(5,2) NOT NULL, slo_score numeric(5,2) NOT NULL, certification_score numeric(5,2) NOT NULL, window_minutes int NOT NULL DEFAULT 60, details jsonb NOT NULL DEFAULT '{}'::jsonb );

CREATE TABLE IF NOT EXISTS public.payment_replay_certifications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, sample_size integer NOT NULL DEFAULT 0, matched integer NOT NULL DEFAULT 0, diverged integer NOT NULL DEFAULT 0, critical boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'running', sample_correlation_ids jsonb NOT NULL DEFAULT '[]'::jsonb, summary jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_replay_simulations ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), requested_by UUID REFERENCES auth.users(id), source_correlation_id TEXT NOT NULL, scenario TEXT NOT NULL, scenario_params JSONB NOT NULL DEFAULT '{}'::jsonb, status TEXT NOT NULL DEFAULT 'running', original_timeline JSONB NOT NULL DEFAULT '[]'::jsonb, simulated_timeline JSONB NOT NULL DEFAULT '[]'::jsonb, divergence JSONB, outcome_summary TEXT, passed_stages TEXT[] NOT NULL DEFAULT '{}', failed_stages TEXT[] NOT NULL DEFAULT '{}', started_at TIMESTAMPTZ NOT NULL DEFAULT now(), finished_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_risk_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id uuid NOT NULL REFERENCES public.mpesa_transactions(id) ON DELETE RESTRICT, rule text NOT NULL, severity public.risk_severity NOT NULL, details jsonb NOT NULL DEFAULT '{}'::jsonb, reviewed_by uuid, reviewed_at timestamptz, resolution text, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_schema_drift_reports ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ran_at timestamptz NOT NULL DEFAULT now(), manifest_hash text NOT NULL, drift_count integer NOT NULL DEFAULT 0, missing_columns jsonb NOT NULL DEFAULT '[]'::jsonb, missing_functions jsonb NOT NULL DEFAULT '[]'::jsonb, missing_triggers jsonb NOT NULL DEFAULT '[]'::jsonb, missing_tables jsonb NOT NULL DEFAULT '[]'::jsonb, extras jsonb NOT NULL DEFAULT '{}'::jsonb, passed boolean GENERATED ALWAYS AS (drift_count = 0) STORED );

CREATE TABLE IF NOT EXISTS public.payment_slos ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slo_key text NOT NULL UNIQUE, name text NOT NULL, category text NOT NULL, description text, target_value numeric(14,4) NOT NULL, unit text NOT NULL DEFAULT 'percent', comparator text NOT NULL DEFAULT '>=', window_minutes integer NOT NULL DEFAULT 60, metric_query text NOT NULL, severity text NOT NULL DEFAULT 'high', active boolean NOT NULL DEFAULT true, config jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_stability_windows ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), window_start timestamptz NOT NULL, window_end timestamptz NOT NULL, callback_success_pct numeric NOT NULL DEFAULT 0, regressions_count integer NOT NULL DEFAULT 0, financial_integrity_score numeric NOT NULL DEFAULT 0, evidence_integrity_score numeric NOT NULL DEFAULT 0, schema_consistency_score numeric NOT NULL DEFAULT 0, continuous_qualification_pass_rate numeric NOT NULL DEFAULT 0, critical_incidents integer NOT NULL DEFAULT 0, stability_score numeric NOT NULL DEFAULT 0, gate_status text NOT NULL DEFAULT 'PENDING', created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_state_transitions ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), correlation_id UUID NOT NULL, payment_attempt_id UUID, from_state TEXT, to_state TEXT NOT NULL CHECK (to_state IN ( 'INITIATED','SESSION_CREATED','ATTEMPT_CREATED','STK_REQUESTED', 'TOKEN_GRANTED','DARAJA_ACCEPTED','CUSTOMER_PROMPTED','CALLBACK_RECEIVED', 'VALIDATED','PROCESSING','WALLET_UPDATED','LEDGER_POSTED','SETTLED', 'COMPLETED','FAILED','TIMED_OUT','CANCELLED' )), actor TEXT, source_function TEXT, reason TEXT, evidence JSONB NOT NULL DEFAULT '{}', occurred_at TIMESTAMPTZ NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_step_traces ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), correlation_id uuid NOT NULL, invocation_id uuid, payment_attempt_id uuid, function_name text NOT NULL, step_number int NOT NULL, step_key text NOT NULL, step_name text, status text NOT NULL CHECK (status IN ('STARTED','OK','SKIPPED','FAILED','TIMED_OUT','RETRIED')), latency_ms int, error_code text, error_message text, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, occurred_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.platform_wallet ( id boolean PRIMARY KEY DEFAULT true CHECK (id), currency text NOT NULL DEFAULT 'KES', float_cents bigint NOT NULL DEFAULT 0, custody_cents bigint NOT NULL DEFAULT 0 CHECK (custody_cents >= 0), liability_cents bigint NOT NULL DEFAULT 0 CHECK (liability_cents >= 0), income_cents bigint NOT NULL DEFAULT 0, lifetime_funded_cents bigint NOT NULL DEFAULT 0, lifetime_client_cents bigint NOT NULL DEFAULT 0, lifetime_released_cents bigint NOT NULL DEFAULT 0, lifetime_paid_out_cents bigint NOT NULL DEFAULT 0, funding_msisdn text NOT NULL DEFAULT '254710100090', paybill text NOT NULL DEFAULT '4148095', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.platform_wallet_ledger ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entry_type text NOT NULL CHECK (entry_type IN ('FUNDING','CLIENT_PAYMENT','FULFILMENT_RELEASE','WITHDRAWAL_PAID','WITHDRAWAL_FEE_INCOME')), amount_cents bigint NOT NULL CHECK (amount_cents >= 0), float_delta bigint NOT NULL DEFAULT 0, custody_delta bigint NOT NULL DEFAULT 0, liability_delta bigint NOT NULL DEFAULT 0, income_delta bigint NOT NULL DEFAULT 0, float_after bigint NOT NULL, custody_after bigint NOT NULL, liability_after bigint NOT NULL, income_after bigint NOT NULL, currency text NOT NULL DEFAULT 'KES', provider_user_id uuid, source_kind text NOT NULL, source_id uuid, reference text NOT NULL, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (entry_type, reference) );

CREATE TABLE IF NOT EXISTS public.proforma_invoices ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), proforma_no text UNIQUE, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','issued','sent','accepted','expired','void')), customer_company text NOT NULL DEFAULT '', customer_address text, customer_pin text, customer_contact_person text, customer_email text, customer_phone text, customer_ref text, quote_reference text, contract_reference text, service_from date, service_to date, payment_terms text NOT NULL DEFAULT '50% Advance, Balance within 30 Days', currency text NOT NULL DEFAULT 'KES', vat_rate numeric(5,2) NOT NULL DEFAULT 16.00, vat_inclusive boolean NOT NULL DEFAULT false, issue_date date, valid_until date, notes text, authorised_name text, authorised_title text, account_id uuid, lead_id uuid, opportunity_id uuid, subtotal_cents bigint NOT NULL DEFAULT 0, vat_cents bigint NOT NULL DEFAULT 0, total_cents bigint NOT NULL DEFAULT 0, owner_staff_id uuid, created_by uuid, issued_at timestamptz, sent_at timestamptz, sent_to text, pdf_sha256 text, void_reason text, is_test boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.proforma_invoices ADD COLUMN IF NOT EXISTS submitted_at timestamptz, ADD COLUMN IF NOT EXISTS submitted_by uuid, ADD COLUMN IF NOT EXISTS approved_at timestamptz, ADD COLUMN IF NOT EXISTS approved_by uuid, ADD COLUMN IF NOT EXISTS approval_note text, ADD COLUMN IF NOT EXISTS sole_approver boolean NOT NULL DEFAULT false;
ALTER TABLE public.proforma_invoices ADD COLUMN IF NOT EXISTS booked_for text, ADD COLUMN IF NOT EXISTS booked_by text;
ALTER TABLE public.proforma_invoices ADD COLUMN IF NOT EXISTS recipient_flagged boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS recipient_flag_reason text;
CREATE TABLE IF NOT EXISTS public.provider_invoices ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_number text UNIQUE, provider_user_id uuid NOT NULL, period_start date NOT NULL, period_end date NOT NULL, currency text NOT NULL DEFAULT 'KES', lines_count integer NOT NULL DEFAULT 0, gross_cents bigint NOT NULL DEFAULT 0, commission_bps integer NOT NULL DEFAULT 1500, commission_cents bigint NOT NULL DEFAULT 0, net_cents bigint NOT NULL DEFAULT 0, withdrawal_fee_bps integer NOT NULL DEFAULT 500, estimated_fee_cents bigint NOT NULL DEFAULT 0, state text NOT NULL DEFAULT 'DRAFT' CHECK (state IN ('DRAFT','SUBMITTED','APPROVED','QUERIED')), submitted_at timestamptz, decided_by uuid, decided_at timestamptz, decision_note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.provider_payout_accounts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_user_id uuid NOT NULL, msisdn text NOT NULL, account_name text NOT NULL, is_default boolean NOT NULL DEFAULT true, verification_state text NOT NULL DEFAULT 'IN_REVIEW' CHECK (verification_state IN ('IN_REVIEW','VERIFIED','REJECTED')), verification_note text, verified_by uuid, verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (provider_user_id, msisdn) );

CREATE TABLE IF NOT EXISTS public.provider_payout_approval_tiers ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), label text NOT NULL UNIQUE, min_cents bigint NOT NULL DEFAULT 0, max_cents bigint, required_approvals integer NOT NULL DEFAULT 1 CHECK (required_approvals BETWEEN 1 AND 3), requires_dual_release boolean NOT NULL DEFAULT false, sla_hours integer NOT NULL DEFAULT 8 CHECK (sla_hours > 0), sort_order integer NOT NULL DEFAULT 0, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.provider_settlement_settings ( id boolean PRIMARY KEY DEFAULT true CHECK (id), commission_bps integer NOT NULL DEFAULT 1500 CHECK (commission_bps BETWEEN 0 AND 10000), platform_paybill text NOT NULL DEFAULT '4148095', min_payout_cents bigint NOT NULL DEFAULT 1000 CHECK (min_payout_cents >= 1000), currency text NOT NULL DEFAULT 'KES', auto_prepare boolean NOT NULL DEFAULT true, requires_finance_approval boolean NOT NULL DEFAULT true, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.provider_settlement_settings ADD COLUMN IF NOT EXISTS withdrawal_fee_bps integer NOT NULL DEFAULT 500;
ALTER TABLE public.provider_settlement_settings ADD COLUMN IF NOT EXISTS payout_shortcode text;
ALTER TABLE public.provider_settlement_settings ADD COLUMN IF NOT EXISTS require_invoice_approval boolean NOT NULL DEFAULT true;
CREATE TABLE IF NOT EXISTS public.provider_wallet_ledger ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_user_id uuid NOT NULL, entry_type text NOT NULL CHECK (entry_type IN ('HOLD','RELEASE','WITHDRAWAL_RESERVED','WITHDRAWAL_FEE','WITHDRAWAL_PAID','WITHDRAWAL_RETURNED')), amount_cents bigint NOT NULL CHECK (amount_cents >= 0), available_delta bigint NOT NULL DEFAULT 0, held_delta bigint NOT NULL DEFAULT 0, reserved_delta bigint NOT NULL DEFAULT 0, available_after bigint NOT NULL, held_after bigint NOT NULL, reserved_after bigint NOT NULL, currency text NOT NULL DEFAULT 'KES', reference text NOT NULL, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (provider_user_id, entry_type, reference) );

CREATE TABLE IF NOT EXISTS public.provider_wallets ( provider_user_id uuid PRIMARY KEY, currency text NOT NULL DEFAULT 'KES', available_cents bigint NOT NULL DEFAULT 0 CHECK (available_cents >= 0), held_cents bigint NOT NULL DEFAULT 0 CHECK (held_cents >= 0), reserved_cents bigint NOT NULL DEFAULT 0 CHECK (reserved_cents >= 0), lifetime_earned_cents bigint NOT NULL DEFAULT 0, lifetime_withdrawn_cents bigint NOT NULL DEFAULT 0, lifetime_fees_cents bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.rental_fleet_units ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vehicle_id uuid UNIQUE REFERENCES public.vehicles(id) ON DELETE SET NULL, plate text NOT NULL UNIQUE, make text NOT NULL, model text NOT NULL, year integer, seats integer, transmission text, home_branch text, asset_class text, band_label text, self_drive boolean NOT NULL DEFAULT false, chauffeur boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'UNDER_SERVICE' CHECK (status IN ('AVAILABLE','UNDER_SERVICE','RETIRED')), provenance text NOT NULL DEFAULT 'MANUAL', notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.rental_fleet_units ADD COLUMN IF NOT EXISTS provider_id uuid;
CREATE TABLE IF NOT EXISTS public.rental_ledger_accounts ( account text PRIMARY KEY, label text NOT NULL, normal_side text NOT NULL CHECK (normal_side IN ('DEBIT','CREDIT')), note text );

CREATE TABLE IF NOT EXISTS public.rental_quote_requests ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference text NOT NULL UNIQUE, token text NOT NULL UNIQUE, category text NOT NULL CHECK (category IN ('SELF_DRIVE','CHAUFFEUR')), asset_class text NOT NULL, band_label text NOT NULL, seats integer, pricing_version integer NOT NULL, pricing_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, snapshot_hash text NOT NULL, start_date date NOT NULL, end_date date NOT NULL, rental_days integer NOT NULL CHECK (rental_days BETWEEN 1 AND 365), extra_hours integer NOT NULL DEFAULT 0 CHECK (extra_hours BETWEEN 0 AND 12), expected_km integer NOT NULL DEFAULT 0 CHECK (expected_km >= 0 AND expected_km <= 100000), pickup_location text NOT NULL, notes text, contact_name text NOT NULL, contact_email text NOT NULL, contact_phone text NOT NULL, company_name text, base_kes numeric(14,2) NOT NULL, extra_hours_kes numeric(14,2) NOT NULL DEFAULT 0, excess_km_kes numeric(14,2) NOT NULL DEFAULT 0, discount_kes numeric(14,2) NOT NULL DEFAULT 0, vat_kes numeric(14,2) NOT NULL, total_kes numeric(14,2) NOT NULL, currency text NOT NULL DEFAULT 'KES', status text NOT NULL DEFAULT 'QUOTED' CHECK (status IN ('QUOTED','AWAITING_PAYMENT','PAID','CONFIRMED','EXPIRED','CANCELLED')), payment_status text NOT NULL DEFAULT 'pending' CHECK (payment_status IN ('pending','paid')), amount_paid_kes numeric(14,2) NOT NULL DEFAULT 0, mpesa_receipt text, paid_at timestamptz, expires_at timestamptz NOT NULL, source_page text, requested_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.rental_quote_requests ADD COLUMN IF NOT EXISTS correlation_id uuid NOT NULL DEFAULT gen_random_uuid();
CREATE TABLE IF NOT EXISTS public.suspicious_transactions ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), transaction_ref UUID, source TEXT NOT NULL, entity_type public.risk_entity_type NOT NULL, entity_id UUID, amount NUMERIC(14,2), currency TEXT DEFAULT 'KES', reason TEXT NOT NULL, score NUMERIC(5,2), severity public.risk_event_severity NOT NULL DEFAULT 'medium', reviewed BOOLEAN NOT NULL DEFAULT false, reviewed_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, reviewed_at TIMESTAMPTZ, outcome TEXT, metadata JSONB NOT NULL DEFAULT '{}'::JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.tax_audit_logs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_kind text NOT NULL, entity_id uuid, event_type public.tax_audit_event NOT NULL, old_value jsonb, new_value jsonb, actor_id uuid, actor_type text NOT NULL DEFAULT 'user', ip_address inet, request_id text, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.tax_frameworks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), country_code text NOT NULL, framework_code text NOT NULL, framework_name text NOT NULL, vat_rate_bps int, withholding_rate_bps int, authority_name text, active boolean NOT NULL DEFAULT true, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (country_code, framework_code));

CREATE TABLE IF NOT EXISTS public.tax_report_sync_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id text NOT NULL, report text NOT NULL, trigger_source text NOT NULL, attempt integer NOT NULL DEFAULT 1, backoff_ms integer, duration_ms integer, status text NOT NULL, window_from date, window_to date, last_error jsonb, triggered_by uuid, triggered_by_email text, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT tax_report_sync_runs_status_check CHECK (status IN ('success','failed')), CONSTRAINT tax_report_sync_runs_trigger_check CHECK (trigger_source IN ('initial_load','auto_retry','manual_retry','retry_job','scheduled')), CONSTRAINT tax_report_sync_runs_attempt_check CHECK (attempt >= 1) );

CREATE TABLE IF NOT EXISTS public.tax_schemes ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, kind public.tax_scheme_kind NOT NULL, jurisdiction text NOT NULL DEFAULT 'KE', description text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.wallet_abuse_cases ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), case_number TEXT NOT NULL UNIQUE DEFAULT ('WA-' || to_char(now(),'YYYYMMDD') || '-' || substr(gen_random_uuid()::text,1,8)), wallet_ref UUID, entity_type public.risk_entity_type NOT NULL, entity_id UUID, abuse_type TEXT NOT NULL, status public.fraud_review_status NOT NULL DEFAULT 'open', severity public.risk_event_severity NOT NULL DEFAULT 'medium', velocity_window TEXT, velocity_count INT, total_amount NUMERIC(14,2), signals JSONB NOT NULL DEFAULT '[]'::JSONB, assigned_to UUID REFERENCES auth.users(id) ON DELETE SET NULL, resolved_at TIMESTAMPTZ, notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.wallet_reconciliation ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), wallet_id uuid NOT NULL REFERENCES public.wallets(id) ON DELETE RESTRICT, period_start timestamptz NOT NULL, period_end timestamptz NOT NULL, opening_balance bigint NOT NULL, credits bigint NOT NULL DEFAULT 0, debits bigint NOT NULL DEFAULT 0, closing_balance bigint NOT NULL, expected_balance bigint NOT NULL, variance bigint GENERATED ALWAYS AS (closing_balance - expected_balance) STORED, status public.reconciliation_status NOT NULL DEFAULT 'PENDING_REVIEW', notes text, reviewed_by uuid, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT wallet_recon_period_chk CHECK (period_end > period_start) );

CREATE TABLE IF NOT EXISTS public.yalla_payment_channels ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), channel_type text NOT NULL CHECK (channel_type IN ('MPESA_PAYBILL','BANK_ACCOUNT')), display_name text NOT NULL, paybill_number text, bank_name text, account_name text, account_number text, branch text, reference_instructions text NOT NULL DEFAULT 'Use your booking reference as the account/reference.', currency text NOT NULL DEFAULT 'KES', is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.yalla_payment_channels ADD COLUMN IF NOT EXISTS source_document text;
CREATE TABLE IF NOT EXISTS public.approval_workflows ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE CASCADE, name text NOT NULL, description text, trigger_predicate jsonb NOT NULL DEFAULT '{}'::jsonb, active boolean NOT NULL DEFAULT true, sla_minutes int NOT NULL DEFAULT 1440, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.chargebacks ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dispute_id uuid REFERENCES public.payment_disputes(id) ON DELETE SET NULL, transaction_id uuid REFERENCES public.mpesa_transactions(id), provider text NOT NULL, provider_ref text NOT NULL, amount_cents bigint NOT NULL CHECK (amount_cents > 0), currency text NOT NULL DEFAULT 'KES', status text NOT NULL DEFAULT 'RECEIVED' CHECK (status IN ('RECEIVED','ACCEPTED','CONTESTED','LOST','WON')), received_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE (provider, provider_ref) );

CREATE TABLE IF NOT EXISTS public.charter_quotes ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference text NOT NULL UNIQUE, user_id uuid, category_slug text NOT NULL, inventory_id uuid REFERENCES public.charter_inventory(id) ON DELETE SET NULL, asset_name text NOT NULL, duration numeric NOT NULL CHECK (duration > 0), quantity integer NOT NULL DEFAULT 1 CHECK (quantity > 0), controls jsonb NOT NULL DEFAULT '[]'::jsonb, cost_settings jsonb NOT NULL DEFAULT '{}'::jsonb, breakdown jsonb NOT NULL DEFAULT '{}'::jsonb, trip jsonb NOT NULL DEFAULT '{}'::jsonb, contact jsonb NOT NULL DEFAULT '{}'::jsonb, currency text NOT NULL DEFAULT 'USD', total numeric NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'requested' CHECK (status IN ('requested','priced','accepted','declined','expired','converted')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.charter_quotes ADD COLUMN IF NOT EXISTS pricing_version INTEGER NOT NULL DEFAULT 0;
ALTER TABLE public.charter_quotes ADD COLUMN IF NOT EXISTS rfq_state text CHECK (rfq_state IN ('REQUESTED','SOURCING','OPTIONS_FOUND','QUOTED','CUSTOMER_REVIEW', 'NEGOTIATION','OPERATOR_CONFIRMED','CUSTOMER_ACCEPTED','DEPOSIT_PENDING', 'BOOKED','COMPLETED','CANCELLED')), ADD COLUMN IF NOT EXISTS rfq_state_at timestamptz;
CREATE TABLE IF NOT EXISTS public.charter_wallet_funding_limits ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), wallet_id uuid REFERENCES public.charter_corporate_wallets(id) ON DELETE CASCADE, per_txn_max_kes numeric NOT NULL DEFAULT 250000, daily_max_kes numeric NOT NULL DEFAULT 1000000, monthly_max_kes numeric NOT NULL DEFAULT 10000000, approval_threshold_kes numeric NOT NULL DEFAULT 500000, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.charter_wallet_funding_limits ADD COLUMN IF NOT EXISTS actor_id uuid, ADD COLUMN IF NOT EXISTS department text, ADD COLUMN IF NOT EXISTS label text;
CREATE TABLE IF NOT EXISTS public.charter_wallet_funding_requests ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), wallet_id uuid NOT NULL REFERENCES public.charter_corporate_wallets(id) ON DELETE CASCADE, owner_id uuid NOT NULL, actor_id uuid, amount_kes numeric NOT NULL CHECK (amount_kes > 0), cost_center text NOT NULL, purpose text, approver_name text, approver_title text, reference text NOT NULL UNIQUE, idempotency_key text NOT NULL UNIQUE, phone text, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','stk_requested','awaiting_callback','paid','failed','cancelled','expired','reversed','refunded')), merchant_request_id text, checkout_request_id text, mpesa_receipt text, result_code integer, result_desc text, ledger_entry_id uuid, requires_approval boolean NOT NULL DEFAULT false, expires_at timestamptz NOT NULL DEFAULT (now() + interval '30 minutes'), paid_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.charter_wallet_funding_requests ADD COLUMN IF NOT EXISTS department text, ADD COLUMN IF NOT EXISTS stk_attempts integer NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS last_stk_at timestamptz, ADD COLUMN IF NOT EXISTS reversal_reason text, ADD COLUMN IF NOT EXISTS reversal_evidence jsonb, ADD COLUMN IF NOT EXISTS reversed_by uuid, ADD COLUMN IF NOT EXISTS reversed_at timestamptz;
CREATE TABLE IF NOT EXISTS public.charter_wallet_reconciliation_attempts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requested_from timestamptz NOT NULL, requested_to timestamptz NOT NULL, status text NOT NULL DEFAULT 'queued', attempt integer NOT NULL DEFAULT 1, retry_of uuid REFERENCES public.charter_wallet_reconciliation_attempts(id) ON DELETE SET NULL, run_id uuid REFERENCES public.charter_wallet_reconciliation_runs(id) ON DELETE SET NULL, findings integer NOT NULL DEFAULT 0, critical integer NOT NULL DEFAULT 0, error text, note text, requested_by uuid, created_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, finished_at timestamptz );

CREATE TABLE IF NOT EXISTS public.charter_wallet_reconciliation_findings ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES public.charter_wallet_reconciliation_runs(id) ON DELETE CASCADE, severity text NOT NULL, kind text NOT NULL, wallet_id uuid, funding_request_id uuid, expected_kes numeric, actual_kes numeric, detail text NOT NULL, created_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.charter_wallet_reconciliation_findings ADD COLUMN IF NOT EXISTS resolution_status text NOT NULL DEFAULT 'open', ADD COLUMN IF NOT EXISTS resolution_notes text, ADD COLUMN IF NOT EXISTS acknowledged_at timestamptz, ADD COLUMN IF NOT EXISTS acknowledged_by uuid, ADD COLUMN IF NOT EXISTS resolved_at timestamptz, ADD COLUMN IF NOT EXISTS resolved_by uuid;
CREATE TABLE IF NOT EXISTS public.commercial_transactions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transaction_ref text NOT NULL UNIQUE DEFAULT public.next_commercial_transaction_id(), origin_path text NOT NULL DEFAULT 'direct_digital', service_line text NOT NULL, status text NOT NULL DEFAULT 'intent', customer_kind text NOT NULL DEFAULT 'individual', customer_user_id uuid, corporate_id uuid, provider_kind text, provider_ref text, driver_id uuid, vehicle_id uuid, opportunity_id uuid REFERENCES public.commercial_opportunities(id) ON DELETE SET NULL, demand_intent_ref text, quote_id uuid, offer_ref text, commitment_id uuid, booking_id uuid, booking_table text, dispatch_assignment_id uuid, invoice_id uuid, invoice_table text, payment_id uuid, payment_table text, settlement_id uuid, revenue_event_id uuid, commercial_action_id uuid REFERENCES public.commercial_actions(id) ON DELETE SET NULL, currency text NOT NULL DEFAULT 'KES', customer_charge_cents bigint, gross_transaction_value_cents bigint, tax_cents bigint NOT NULL DEFAULT 0, adjustment_cents bigint NOT NULL DEFAULT 0, partner_entitlement_cents bigint, platform_revenue_cents bigint, payment_cost_cents bigint NOT NULL DEFAULT 0, refund_cents bigint NOT NULL DEFAULT 0, incentive_cents bigint NOT NULL DEFAULT 0, contribution_cents bigint, committed_at timestamptz, accepted_at timestamptz, booked_at timestamptz, fulfilled_at timestamptz, fulfilment_source text, financially_eligible boolean NOT NULL DEFAULT false, eligibility_reason text, recognised_at timestamptz, cancelled_at timestamptz, provenance text NOT NULL DEFAULT 'LIVE', economics_complete boolean NOT NULL DEFAULT false, missing_fields jsonb NOT NULL DEFAULT '[]'::jsonb, lineage jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT commercial_transactions_origin_check CHECK (origin_path = ANY (ARRAY['assisted_enterprise','direct_digital','backfill'])), CONSTRAINT commercial_transactions_status_check CHECK (status = ANY (ARRAY['intent','offered','committed','accepted','booked','orchestrating','fulfilled','invoiced','paid','settled','recognised','closed','cancelled','failed'])), CONSTRAINT commercial_transactions_customer_kind_check CHECK (customer_kind = ANY (ARRAY['corporate','individual','partner','government'])), CONSTRAINT commercial_transactions_provenance_check CHECK (provenance = ANY (ARRAY['LIVE','MODELLED','SIMULATED','SEEDED','INCOMPLETE'])), CONSTRAINT commercial_transactions_booking_unique UNIQUE (booking_table, booking_id) );
ALTER TABLE public.commercial_transactions ADD COLUMN IF NOT EXISTS payment_ref text, ADD COLUMN IF NOT EXISTS payment_status text, ADD COLUMN IF NOT EXISTS payment_provider text, ADD COLUMN IF NOT EXISTS paid_at timestamptz, ADD COLUMN IF NOT EXISTS financials_source text, ADD COLUMN IF NOT EXISTS financial_review_status text NOT NULL DEFAULT 'pending', ADD COLUMN IF NOT EXISTS financial_reviewed_by uuid, ADD COLUMN IF NOT EXISTS financial_reviewed_at timestamptz, ADD COLUMN IF NOT EXISTS financial_review_notes text;
ALTER TABLE public.commercial_transactions ADD COLUMN IF NOT EXISTS payment_evidence_kind text, ADD COLUMN IF NOT EXISTS integrity_flags jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.commercial_transactions ADD COLUMN IF NOT EXISTS financial_confidence numeric(5,2), ADD COLUMN IF NOT EXISTS financial_auto_approved boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS financial_confidence_factors jsonb;
CREATE TABLE IF NOT EXISTS public.corporate_bank_guarantees ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE RESTRICT, guarantee_number text NOT NULL, issuing_bank text NOT NULL, beneficiary text NOT NULL DEFAULT 'Yalla Mobility', legal_entity_name text NOT NULL, guaranteed_amount_cents bigint NOT NULL CHECK (guaranteed_amount_cents > 0), currency text NOT NULL DEFAULT 'KES', issue_date date NOT NULL, effective_date date NOT NULL, expiry_date date NOT NULL, claim_expiry_date date, document_reference text, document_storage_path text, document_sha256 text, state public.bank_guarantee_state NOT NULL DEFAULT 'UPLOADED', external_verification_required boolean NOT NULL DEFAULT true, verification_note text, rejection_reason text, created_by uuid, verified_by uuid, verified_at timestamptz, approved_by uuid, approved_at timestamptz, activated_by uuid, activated_at timestamptz, suspended_at timestamptz, expired_at timestamptz, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (corporate_id, guarantee_number) );

CREATE TABLE IF NOT EXISTS public.corporate_billing_periods ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE RESTRICT, period_start date NOT NULL, period_end date NOT NULL, status public.corporate_period_status NOT NULL DEFAULT 'OPEN', locked_at timestamptz, billed_at timestamptz, settled_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (corporate_id, period_start, period_end), CHECK (period_end >= period_start) );

CREATE TABLE IF NOT EXISTS public.corporate_cash_ledger ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE RESTRICT, entry_type public.corp_ledger_entry_type NOT NULL, amount_cents bigint NOT NULL, balance_after_cents bigint NOT NULL, currency text NOT NULL DEFAULT 'KES', reference text, description text, source_kind text, source_id uuid, occurred_at timestamptz NOT NULL DEFAULT now(), created_by uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.corporate_financial_reconciliation ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), corp_reference TEXT UNIQUE NOT NULL, corporate_id UUID NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE CASCADE, proof_reference TEXT, proof_id UUID, mpesa_receipt TEXT, expected_amount_cents BIGINT NOT NULL DEFAULT 0, proof_amount_cents BIGINT, wallet_amount_cents BIGINT, cash_ledger_amount_cents BIGINT, amount_difference_cents BIGINT NOT NULL DEFAULT 0, proof_status TEXT, wallet_status TEXT, cash_posting_status TEXT, proof_exists BOOLEAN NOT NULL DEFAULT FALSE, wallet_posted BOOLEAN NOT NULL DEFAULT FALSE, ledger_posted BOOLEAN NOT NULL DEFAULT FALSE, duplicate_receipt BOOLEAN NOT NULL DEFAULT FALSE, reconciliation_status public.reconciliation_status_enum NOT NULL DEFAULT 'PENDING_REVIEW', mismatch_reason TEXT, severity public.reconciliation_severity NOT NULL DEFAULT 'LOW', confidence_score NUMERIC(5,2) NOT NULL DEFAULT 100, investigated BOOLEAN NOT NULL DEFAULT FALSE, investigation_started_at TIMESTAMPTZ, last_reconciled_at TIMESTAMPTZ, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.corporate_payment_policies ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE RESTRICT, version integer NOT NULL, credit_rule text NOT NULL DEFAULT 'CREDIT_NOT_ALLOWED' CHECK (credit_rule IN ('CASH_ONLY','CREDIT_NOT_ALLOWED','CREDIT_IF_GUARANTEED','CREDIT_ALLOWED_WITHIN_LIMIT')), max_transaction_cents bigint, daily_credit_exposure_cents bigint, monthly_credit_exposure_cents bigint, approval_threshold_cents bigint, required_approval_role public.app_role, status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','ACTIVE','RETIRED')), business_approval text NOT NULL DEFAULT 'PENDING_BUSINESS_APPROVAL', proposed_by uuid, approved_by uuid, approved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (corporate_id, version), CONSTRAINT cpp_active_needs_approval CHECK (status <> 'ACTIVE' OR (approved_by IS NOT NULL AND approved_at IS NOT NULL)) );

CREATE TABLE IF NOT EXISTS public.cost_centers ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE CASCADE, code text NOT NULL, name text NOT NULL, parent_id uuid REFERENCES public.cost_centers(id) ON DELETE SET NULL, owner_user_id uuid REFERENCES auth.users(id), status public.cost_center_status NOT NULL DEFAULT 'ACTIVE', metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (corporate_id, code) );

CREATE TABLE IF NOT EXISTS public.driver_finance_clearances ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_user_id uuid NOT NULL UNIQUE, driver_id uuid REFERENCES public.drivers(id) ON DELETE SET NULL, application_id uuid REFERENCES public.driver_applications(id) ON DELETE SET NULL, state text NOT NULL DEFAULT 'PENDING', note text, decided_by uuid, decided_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT driver_finance_clearances_state_chk CHECK (state IN ('PENDING','CLEARED','SUSPENDED')) );

CREATE TABLE IF NOT EXISTS public.driver_payout_reconciliation ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid NOT NULL REFERENCES public.driver_payout_batches(id), expected_count int NOT NULL, actual_count int NOT NULL, expected_amount_cents bigint NOT NULL, actual_amount_cents bigint NOT NULL, variance_cents bigint GENERATED ALWAYS AS (expected_amount_cents - actual_amount_cents) STORED, status text NOT NULL, notes text, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.driver_payouts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT, method_id uuid NOT NULL REFERENCES public.driver_payout_methods(id), batch_id uuid REFERENCES public.driver_payout_batches(id), amount_cents bigint NOT NULL CHECK (amount_cents > 0), currency text NOT NULL DEFAULT 'KES', status public.driver_payout_status NOT NULL DEFAULT 'PENDING', reference text, provider_txn_id text, journal_id uuid REFERENCES public.journals(id), reversal_of uuid REFERENCES public.driver_payouts(id), tax_withheld_cents bigint NOT NULL DEFAULT 0, net_payout_cents bigint GENERATED ALWAYS AS (amount_cents - tax_withheld_cents) STORED, requested_by uuid, approved_by uuid, approved_at timestamptz, paid_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['payment_orchestrator_approvals','payment_orchestrator_decisions','payment_orchestrator_env_policy','payment_orchestrator_flag','payment_orchestrator_rollout_stages','payment_orchestrator_shadow_diffs','payment_pci_snapshots','payment_pci_streaks','payment_platform_health','payment_projection_registry','payment_qualification_failure_classes','payment_qualification_reports','payment_rca_classifications','payment_receiving_accounts','payment_regression_fingerprints','payment_reliability_forecasts','payment_reliability_snapshots','payment_replay_certifications','payment_replay_simulations','payment_risk_events','payment_schema_drift_reports','payment_slos','payment_stability_windows','payment_state_transitions','payment_step_traces','platform_wallet','platform_wallet_ledger','proforma_invoices','provider_invoices','provider_payout_accounts','provider_payout_approval_tiers','provider_settlement_settings','provider_wallet_ledger','provider_wallets','rental_fleet_units','rental_ledger_accounts','rental_quote_requests','suspicious_transactions','tax_audit_logs','tax_frameworks','tax_report_sync_runs','tax_schemes','wallet_abuse_cases','wallet_reconciliation','yalla_payment_channels','approval_workflows','chargebacks','charter_quotes','charter_wallet_funding_limits','charter_wallet_funding_requests','charter_wallet_reconciliation_attempts','charter_wallet_reconciliation_findings','commercial_transactions','corporate_bank_guarantees','corporate_billing_periods','corporate_cash_ledger','corporate_financial_reconciliation','corporate_payment_policies','cost_centers','driver_finance_clearances','driver_payout_reconciliation','driver_payouts'] LOOP EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t); EXECUTE format('GRANT ALL ON public.%I TO service_role', t); EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('CREATE POLICY "Admins manage restored records" ON public.%I FOR ALL TO authenticated USING (public.has_any_role(auth.uid(), ARRAY[''admin'',''super_admin'',''finance_admin'']::public.app_role[])) WITH CHECK (public.has_any_role(auth.uid(), ARRAY[''admin'',''super_admin'',''finance_admin'']::public.app_role[]))', t); END LOOP; END $$;CREATE TABLE IF NOT EXISTS public.driver_tax_liabilities ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, period_start date NOT NULL, period_end date NOT NULL, scheme_code text NOT NULL, taxable_cents bigint NOT NULL DEFAULT 0, rate_bps int NOT NULL, amount_cents bigint NOT NULL DEFAULT 0, paid_cents bigint NOT NULL DEFAULT 0, due_date date NOT NULL, status public.driver_tax_liability_status NOT NULL DEFAULT 'OPEN', journal_id uuid REFERENCES public.journals(id), metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (driver_id, period_start, period_end, scheme_code) );

CREATE TABLE IF NOT EXISTS public.etims_invoice_items ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES public.etims_invoices(id) ON DELETE CASCADE, line_number int NOT NULL, description text NOT NULL, hs_code text, item_code text, quantity numeric(18,4) NOT NULL DEFAULT 1 CHECK (quantity > 0), unit_price_cents bigint NOT NULL CHECK (unit_price_cents >= 0), discount_cents bigint NOT NULL DEFAULT 0 CHECK (discount_cents >= 0), tax_scheme_code text NOT NULL REFERENCES public.tax_schemes(code), tax_rate_bps int NOT NULL DEFAULT 0 CHECK (tax_rate_bps >= 0), taxable_cents bigint NOT NULL CHECK (taxable_cents >= 0), tax_cents bigint NOT NULL DEFAULT 0 CHECK (tax_cents >= 0), total_cents bigint NOT NULL CHECK (total_cents >= 0), metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (invoice_id, line_number) );

CREATE TABLE IF NOT EXISTS public.exchange_rates ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), base_currency text NOT NULL REFERENCES public.currencies(code), quote_currency text NOT NULL REFERENCES public.currencies(code), rate_date date NOT NULL, rate_type public.fx_rate_type NOT NULL DEFAULT 'DAILY', rate numeric(20,10) NOT NULL CHECK (rate > 0), provider text NOT NULL DEFAULT 'manual', created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, UNIQUE (base_currency, quote_currency, rate_date, rate_type) );

CREATE TABLE IF NOT EXISTS public.freight_consignments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL UNIQUE REFERENCES public.delivery_orders(id) ON DELETE CASCADE, consignment_number text NOT NULL UNIQUE, service_level text NOT NULL DEFAULT 'STANDARD', cargo_type text NOT NULL, commodity text, package_type text, pieces integer NOT NULL DEFAULT 1, gross_weight_kg numeric(12,3) NOT NULL, volume_cbm numeric(12,4), chargeable_weight_kg numeric(12,3), declared_value numeric(14,2), currency text NOT NULL DEFAULT 'KES', fragile boolean NOT NULL DEFAULT false, hazardous boolean NOT NULL DEFAULT false, hazard_class text, temp_min_c numeric(5,2), temp_max_c numeric(5,2), loading_requirements text[] NOT NULL DEFAULT '{}', special_handling text[] NOT NULL DEFAULT '{}', shipper_name text, shipper_phone text, consignee_name text, consignee_phone text, origin_hub_id uuid REFERENCES public.logistics_hubs(id), destination_hub_id uuid REFERENCES public.logistics_hubs(id), delivery_address text, delivery_lat numeric(10,6), delivery_lng numeric(10,6), delivery_window_start timestamptz, delivery_window_end timestamptz, notes text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT freight_consignments_pieces_positive CHECK (pieces > 0), CONSTRAINT freight_consignments_weight_positive CHECK (gross_weight_kg > 0), CONSTRAINT freight_consignments_volume_nonneg CHECK (volume_cbm IS NULL OR volume_cbm >= 0), CONSTRAINT freight_consignments_hazard_declared CHECK (NOT hazardous OR hazard_class IS NOT NULL), CONSTRAINT freight_consignments_temp_range CHECK (temp_min_c IS NULL OR temp_max_c IS NULL OR temp_min_c <= temp_max_c), CONSTRAINT freight_consignments_cargo_type CHECK (cargo_type IN ('GENERAL','PALLETISED','CONTAINERISED','BULK','REFRIGERATED','FRAGILE','HAZARDOUS','OVERSIZED','DOCUMENTS')) );

CREATE TABLE IF NOT EXISTS public.freight_quotations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), quote_number text NOT NULL UNIQUE, customer_id uuid, offering_code text NOT NULL DEFAULT 'FREIGHT_CARGO', status text NOT NULL DEFAULT 'ISSUED', currency text NOT NULL DEFAULT 'KES', base_amount numeric(14,2) NOT NULL, surcharges_amount numeric(14,2) NOT NULL DEFAULT 0, tax_amount numeric(14,2) NOT NULL DEFAULT 0, total_amount numeric(14,2) NOT NULL, lines jsonb NOT NULL, rate_plan_id text NOT NULL, rate_plan_version integer NOT NULL, rate_source text NOT NULL DEFAULT 'TARIFF', pricing_version text NOT NULL, snapshot_hash text NOT NULL, inputs jsonb NOT NULL, origin_label text NOT NULL, destination_label text NOT NULL, distance_km numeric(10,2), distance_basis text, vehicle_class text, hub_transfers integer NOT NULL DEFAULT 0, cargo jsonb NOT NULL DEFAULT '{}', items jsonb NOT NULL DEFAULT '[]', planned_legs jsonb NOT NULL DEFAULT '[]', valid_until timestamptz NOT NULL, issued_at timestamptz NOT NULL DEFAULT now(), accepted_at timestamptz, accepted_by uuid, rejected_at timestamptz, rejection_reason text, order_id uuid REFERENCES public.delivery_orders(id) ON DELETE SET NULL, correlation_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT freight_quotations_status CHECK (status IN ('ISSUED','ACCEPTED','CONVERTED','REJECTED','EXPIRED')), CONSTRAINT freight_quotations_total_positive CHECK (total_amount > 0), CONSTRAINT freight_quotations_amounts_nonneg CHECK (base_amount >= 0 AND surcharges_amount >= 0 AND tax_amount >= 0) );

CREATE TABLE IF NOT EXISTS public.freight_requirements ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requirement_number text NOT NULL UNIQUE, tenant_id uuid, customer_id uuid, requested_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, order_id uuid REFERENCES public.delivery_orders(id) ON DELETE SET NULL, enquiry_id uuid REFERENCES public.logistics_enquiries(id) ON DELETE SET NULL, state public.freight_requirement_state NOT NULL DEFAULT 'DRAFT', service_level text NOT NULL DEFAULT 'STANDARD', origin_label text NOT NULL, origin_area_code text, origin_lat numeric, origin_lng numeric, destination_label text NOT NULL, destination_area_code text, destination_lat numeric, destination_lng numeric, corridor text, pickup_window_start timestamptz NOT NULL, pickup_window_end timestamptz NOT NULL, delivery_window_start timestamptz, delivery_window_end timestamptz, weight_kg numeric(12,2) NOT NULL CHECK (weight_kg > 0), volume_cbm numeric(12,3), length_cm numeric(10,1), width_cm numeric(10,1), height_cm numeric(10,1), package_count integer NOT NULL DEFAULT 1 CHECK (package_count > 0), cargo_class text NOT NULL DEFAULT 'GENERAL', goods_code text, handling_requirements text[] NOT NULL DEFAULT '{}', equipment_required text[] NOT NULL DEFAULT '{}', vehicle_type_required text, temperature_controlled boolean NOT NULL DEFAULT false, temperature_min_c numeric(5,1), temperature_max_c numeric(5,1), cross_border boolean NOT NULL DEFAULT false, declared_value numeric(14,2), currency text NOT NULL DEFAULT 'KES', target_budget numeric(14,2), special_instructions text, is_test boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (pickup_window_end >= pickup_window_start), CHECK (delivery_window_end IS NULL OR delivery_window_start IS NULL OR delivery_window_end >= delivery_window_start) );

CREATE TABLE IF NOT EXISTS public.ledger_entries ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), journal_id uuid NOT NULL, account_id uuid NOT NULL REFERENCES public.ledger_accounts(id) ON DELETE RESTRICT, direction public.ledger_direction NOT NULL, amount_cents bigint NOT NULL CHECK (amount_cents > 0), currency text NOT NULL DEFAULT 'KES' CHECK (currency IN ('KES','USD','EUR')), transaction_id uuid REFERENCES public.mpesa_transactions(id) ON DELETE RESTRICT, memo text, posted_by uuid, created_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.ledger_entries ADD COLUMN IF NOT EXISTS base_currency text DEFAULT 'KES', ADD COLUMN IF NOT EXISTS base_amount_cents bigint, ADD COLUMN IF NOT EXISTS fx_rate_id uuid REFERENCES public.exchange_rates(id);
ALTER TABLE public.ledger_entries ADD COLUMN IF NOT EXISTS prev_hash bytea, ADD COLUMN IF NOT EXISTS entry_hash bytea;
CREATE TABLE IF NOT EXISTS public.ledger_snapshots ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), as_of timestamptz NOT NULL, account_id uuid NOT NULL REFERENCES public.ledger_accounts(id), currency text NOT NULL, debits_cents bigint NOT NULL, credits_cents bigint NOT NULL, balance_cents bigint NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, UNIQUE (as_of, account_id, currency) );

CREATE TABLE IF NOT EXISTS public.logistics_manifests ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), manifest_number text NOT NULL UNIQUE DEFAULT 'MAN-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.logistics_manifest_seq')::text, 6, '0'), manifest_type text NOT NULL DEFAULT 'delivery_run' CHECK (manifest_type IN ('pickup_run','line_haul','delivery_run','hub_inbound','hub_outbound','return_run')), status text NOT NULL DEFAULT 'open' CHECK (status IN ('open','closed','assigned','dispatched','received','reconciled','cancelled')), origin_hub_id uuid REFERENCES public.logistics_hubs(id) ON DELETE SET NULL, destination_hub_id uuid REFERENCES public.logistics_hubs(id) ON DELETE SET NULL, assigned_driver_id uuid, vehicle_id uuid, notes text, planned_departure timestamptz, closed_at timestamptz, dispatched_at timestamptz, received_at timestamptz, reconciled_at timestamptz, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.logistics_routes ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), route_number text NOT NULL UNIQUE, organization_id uuid NULL, route_type text NOT NULL DEFAULT 'delivery' CHECK (route_type IN ('delivery','pickup','mixed','linehaul','returns','shuttle')), status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','PLANNED','ASSIGNED','READY','IN_PROGRESS','PAUSED','COMPLETED','FAILED','CANCELLED')), planned_start timestamptz, planned_end timestamptz, actual_start timestamptz, actual_end timestamptz, driver_user_id uuid, vehicle_id uuid REFERENCES public.vehicles(id) ON DELETE SET NULL, origin_hub_id uuid REFERENCES public.logistics_hubs(id) ON DELETE SET NULL, destination_hub_id uuid REFERENCES public.logistics_hubs(id) ON DELETE SET NULL, origin_label text, origin_lat numeric, origin_lng numeric, destination_label text, destination_lat numeric, destination_lng numeric, planned_distance_km numeric CHECK (planned_distance_km IS NULL OR planned_distance_km >= 0), actual_distance_km numeric CHECK (actual_distance_km IS NULL OR actual_distance_km >= 0), estimated_duration_min integer CHECK (estimated_duration_min IS NULL OR estimated_duration_min >= 0), actual_duration_min integer CHECK (actual_duration_min IS NULL OR actual_duration_min >= 0), service_window_start timestamptz, service_window_end timestamptz, required_capacity_kg numeric CHECK (required_capacity_kg IS NULL OR required_capacity_kg >= 0), required_vehicle_type text, optimization_status text NOT NULL DEFAULT 'not_optimized' CHECK (optimization_status IN ('not_optimized','pending','optimized','failed','manual')), current_version integer NOT NULL DEFAULT 1, notes text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.mpesa_callback_logs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_attempt_id uuid REFERENCES public.payment_attempts(id) ON DELETE SET NULL, checkout_request_id text, merchant_request_id text, payload jsonb NOT NULL, headers jsonb, ip_address inet, verified boolean NOT NULL DEFAULT false, verification_notes text, received_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.mpesa_payment_flags ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_attempt_id uuid NOT NULL REFERENCES public.payment_attempts(id), action text NOT NULL CHECK (action IN ('flagged','resolved')), reason text NOT NULL, actor_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.packages ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tracking_number text NOT NULL UNIQUE DEFAULT 'PKG-' || upper(substring(replace(gen_random_uuid()::text,'-',''),1,12)), order_id uuid REFERENCES public.delivery_orders(id) ON DELETE CASCADE, module text NOT NULL, sender_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, sender_name text, sender_phone text, recipient_name text NOT NULL, recipient_phone text NOT NULL, pickup_address text NOT NULL, pickup_lat numeric(10,7), pickup_lng numeric(10,7), dropoff_address text NOT NULL, dropoff_lat numeric(10,7), dropoff_lng numeric(10,7), weight_kg numeric(8,3), length_cm integer, width_cm integer, height_cm integer, declared_value numeric(12,2), currency text NOT NULL DEFAULT 'KES', fragile boolean NOT NULL DEFAULT false, cold_chain boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'created', assigned_driver_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, picked_up_at timestamptz, delivered_at timestamptz, cancelled_at timestamptz, cancellation_reason text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.partners ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_code text NOT NULL UNIQUE, legal_name text NOT NULL, trading_name text, partner_type public.partner_type NOT NULL DEFAULT 'OTHER', status public.partner_status NOT NULL DEFAULT 'pending', verification_status public.partner_verification_status NOT NULL DEFAULT 'unverified', commercial_model public.partner_commercial_model NOT NULL DEFAULT 'BOOK', commission_model public.partner_commission_model NOT NULL DEFAULT 'COMMISSION', partner_margin_pct numeric(6,3) NOT NULL DEFAULT 0, corporate_account_id uuid REFERENCES public.corporate_accounts(id) ON DELETE SET NULL, primary_contact_name text, primary_contact_email text, primary_contact_phone text, country text NOT NULL DEFAULT 'KE', city text, api_access boolean NOT NULL DEFAULT false, white_label boolean NOT NULL DEFAULT false, risk_score numeric(5,2) NOT NULL DEFAULT 0, trust_score numeric(5,2) NOT NULL DEFAULT 0, is_demo boolean NOT NULL DEFAULT false, notes text, created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.partners ADD COLUMN IF NOT EXISTS onboarding_stage public.partner_onboarding_stage NOT NULL DEFAULT 'applied', ADD COLUMN IF NOT EXISTS contract_signed_at timestamptz, ADD COLUMN IF NOT EXISTS activated_at timestamptz;
CREATE TABLE IF NOT EXISTS public.payment_alerts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slo_id uuid REFERENCES public.payment_slos(id) ON DELETE SET NULL, alert_key text NOT NULL, severity text NOT NULL DEFAULT 'high', status text NOT NULL DEFAULT 'FIRING' CHECK (status IN ('FIRING','ACKNOWLEDGED','RESOLVED')), title text NOT NULL, message text NOT NULL, details jsonb NOT NULL DEFAULT '{}'::jsonb, fired_at timestamptz NOT NULL DEFAULT now(), acknowledged_at timestamptz, acknowledged_by uuid, resolved_at timestamptz, pagerduty_dedup_key text, pagerduty_delivered boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.payment_alerts ADD COLUMN IF NOT EXISTS acknowledgement_note text, ADD COLUMN IF NOT EXISTS resolution_note text, ADD COLUMN IF NOT EXISTS resolved_by uuid;
CREATE TABLE IF NOT EXISTS public.payment_audit_logs_v2 ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_attempt_id uuid REFERENCES public.payment_attempts(id) ON DELETE SET NULL, actor text NOT NULL, actor_user_id uuid, action text NOT NULL, request_id text, correlation_id text, jwt_claims jsonb, ip_address inet, headers jsonb, before_state public.payment_state, after_state public.payment_state, payload jsonb, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_certification_baselines ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), environment text NOT NULL UNIQUE, run_id uuid REFERENCES public.payment_certification_runs(id) ON DELETE SET NULL, suite_version text, deployment_version text, git_revision text, readiness_score numeric, overall_score numeric, signal_scores jsonb NOT NULL DEFAULT '{}'::jsonb, metrics jsonb NOT NULL DEFAULT '{}'::jsonb, certified_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_certification_scenarios ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, run_id UUID NOT NULL REFERENCES public.payment_certification_runs(id) ON DELETE CASCADE, scenario_key TEXT NOT NULL, scenario_name TEXT NOT NULL, correlation_id UUID, payment_attempt_id UUID, checkout_request_id TEXT, merchant_request_id TEXT, status TEXT NOT NULL DEFAULT 'PENDING', expected_outcome TEXT NOT NULL, observed_outcome TEXT, gate_results JSONB NOT NULL DEFAULT '[]'::jsonb, evidence JSONB NOT NULL DEFAULT '{}'::jsonb, error_message TEXT, duration_ms INT, started_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_chaos_runs ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), scenario_id UUID NOT NULL REFERENCES public.payment_chaos_scenarios(id), status TEXT NOT NULL DEFAULT 'running' CHECK (status IN ('running','recovered','failed','aborted')), started_at TIMESTAMPTZ NOT NULL DEFAULT now(), finished_at TIMESTAMPTZ, recovery_ms INTEGER, auto_recovered BOOLEAN NOT NULL DEFAULT false, financial_integrity_delta NUMERIC NOT NULL DEFAULT 0, data_loss_detected BOOLEAN NOT NULL DEFAULT false, evidence JSONB NOT NULL DEFAULT '{}'::jsonb, correlation_id TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_continuous_qualification_reruns ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), original_run_id UUID NOT NULL REFERENCES public.payment_continuous_qualification_runs(id) ON DELETE CASCADE, requested_by UUID NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT, reason TEXT NOT NULL, new_run_id UUID REFERENCES public.payment_continuous_qualification_runs(id) ON DELETE SET NULL, status TEXT NOT NULL DEFAULT 'QUEUED' CHECK (status IN ('QUEUED','RUNNING','SUCCEEDED','FAILED')), error_detail TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ );

CREATE TABLE IF NOT EXISTS public.payment_dead_letters ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, payment_attempt_id uuid REFERENCES public.payment_attempts(id) ON DELETE SET NULL, payload jsonb NOT NULL, last_error text, attempts integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','REPLAYING','RESOLVED','BLOCKED')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz );

CREATE TABLE IF NOT EXISTS public.payment_infra_slo_measurements ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slo_key text NOT NULL REFERENCES public.payment_infra_slos(slo_key) ON DELETE CASCADE, observed_value numeric NOT NULL, breach_severity text NOT NULL DEFAULT 'ok' CHECK (breach_severity IN ('ok','warn','critical')), window_seconds integer NOT NULL DEFAULT 60, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, measured_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_notification_dispatches ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), channel_id uuid REFERENCES public.payment_notification_channels(id), channel_type text NOT NULL, event_type text NOT NULL, correlation_id text, severity text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','sent','failed','skipped')), response_code int, response_body text, attempt_count int NOT NULL DEFAULT 0, dispatched_at timestamptz, created_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.payment_notification_dispatches ADD COLUMN IF NOT EXISTS priority TEXT NOT NULL DEFAULT 'normal';
ALTER TABLE public.payment_notification_dispatches ADD COLUMN IF NOT EXISTS trace_id text, ADD COLUMN IF NOT EXISTS span_id text, ADD COLUMN IF NOT EXISTS parent_span_id text, ADD COLUMN IF NOT EXISTS delivery_latency_ms integer, ADD COLUMN IF NOT EXISTS idempotency_key text;
CREATE TABLE IF NOT EXISTS public.payment_projection_incidents ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_attempt_id uuid NOT NULL REFERENCES public.payment_attempts(id) ON DELETE CASCADE, projection_name text NOT NULL, expected_state text NOT NULL, actual_state text, severity text NOT NULL DEFAULT 'high' CHECK (severity IN ('low','medium','high','critical')), opened_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz, resolution_notes text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb );

CREATE TABLE IF NOT EXISTS public.payment_projection_sync_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_attempt_id uuid NOT NULL REFERENCES public.payment_attempts(id) ON DELETE CASCADE, projection_name text NOT NULL REFERENCES public.payment_projection_registry(projection_name), status text NOT NULL CHECK (status IN ('started','completed','failed','skipped')), attempts int NOT NULL DEFAULT 1, last_error text, correlation_id text, trace_id text, before_state text, after_state text, duration_ms int, started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}'::jsonb );

CREATE TABLE IF NOT EXISTS public.payment_qualification_evidence_packs ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), cq_run_id UUID NOT NULL UNIQUE REFERENCES public.payment_continuous_qualification_runs(id) ON DELETE CASCADE, build_version TEXT, git_revision TEXT, migration_version TEXT, correlation_id TEXT, checkout_request_id TEXT, merchant_request_id TEXT, final_verdict TEXT NOT NULL, failure_class TEXT REFERENCES public.payment_qualification_failure_classes(class_key), financial_integrity_score NUMERIC(5,2), reliability_score NUMERIC(5,2), readiness_score NUMERIC(5,2), slo_evaluation JSONB DEFAULT '{}'::jsonb, canonical_payload JSONB NOT NULL, canonical_sha256 TEXT NOT NULL, signature TEXT NOT NULL, signing_key_id TEXT NOT NULL DEFAULT 'default', signature_algorithm TEXT NOT NULL DEFAULT 'HMAC-SHA256', created_at TIMESTAMPTZ NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_qualification_step_traces ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), cq_run_id UUID NOT NULL REFERENCES public.payment_continuous_qualification_runs(id) ON DELETE CASCADE, step_index INT NOT NULL, step_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING', started_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ, latency_ms INT, correlation_id TEXT, evidence_ref JSONB DEFAULT '{}'::jsonb, error_class TEXT, error_message TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_replay_cert_divergences ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), certification_id uuid NOT NULL REFERENCES public.payment_replay_certifications(id) ON DELETE CASCADE, correlation_id text NOT NULL, dimension text NOT NULL, expected jsonb, actual jsonb, severity text NOT NULL DEFAULT 'medium', detected_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_slo_measurements ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slo_id uuid NOT NULL REFERENCES public.payment_slos(id) ON DELETE CASCADE, measured_at timestamptz NOT NULL DEFAULT now(), window_start timestamptz NOT NULL, window_end timestamptz NOT NULL, numerator bigint NOT NULL, denominator bigint NOT NULL, actual_value numeric(14,4) NOT NULL, target_value numeric(14,4) NOT NULL, compliant boolean NOT NULL, burn_rate numeric(10,3), details jsonb NOT NULL DEFAULT '{}'::jsonb );

CREATE TABLE IF NOT EXISTS public.proforma_invoice_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), proforma_id uuid NOT NULL REFERENCES public.proforma_invoices(id) ON DELETE CASCADE, event text NOT NULL, status_before text, status_after text, note text, detail jsonb NOT NULL DEFAULT '{}'::jsonb, actor_id uuid, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.proforma_invoice_lines ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), proforma_id uuid NOT NULL REFERENCES public.proforma_invoices(id) ON DELETE CASCADE, line_no integer NOT NULL, description text NOT NULL DEFAULT '', service_date date, vehicle_category text, qty numeric(12,2) NOT NULL DEFAULT 1, unit_rate_cents bigint NOT NULL DEFAULT 0, amount_cents bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (proforma_id, line_no) );

CREATE TABLE IF NOT EXISTS public.provider_invoice_lines ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES public.provider_invoices(id) ON DELETE CASCADE, earning_id uuid NOT NULL, booking_reference text NOT NULL, service_date date, gross_cents bigint NOT NULL, commission_cents bigint NOT NULL, net_cents bigint NOT NULL, currency text NOT NULL DEFAULT 'KES', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (invoice_id, earning_id) );

CREATE TABLE IF NOT EXISTS public.provider_payout_requests ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_reference text NOT NULL UNIQUE, provider_user_id uuid NOT NULL, account_id uuid NOT NULL REFERENCES public.provider_payout_accounts(id), msisdn text NOT NULL, amount_cents bigint NOT NULL CHECK (amount_cents > 0), currency text NOT NULL DEFAULT 'KES', earnings_count integer NOT NULL DEFAULT 0, state text NOT NULL DEFAULT 'PENDING_APPROVAL' CHECK (state IN ('PENDING_APPROVAL','APPROVED','PROCESSING','PAID','FAILED','CANCELLED')), approved_by uuid, approved_at timestamptz, decision_note text, disbursement_id uuid, provider_transaction_id text, paid_at timestamptz, failure_reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.provider_payout_requests ADD COLUMN IF NOT EXISTS gross_cents bigint, ADD COLUMN IF NOT EXISTS fee_bps integer, ADD COLUMN IF NOT EXISTS fee_cents bigint;
ALTER TABLE public.provider_payout_requests ADD COLUMN IF NOT EXISTS submitted_at timestamptz NOT NULL DEFAULT now(), ADD COLUMN IF NOT EXISTS tier_id uuid REFERENCES public.provider_payout_approval_tiers(id), ADD COLUMN IF NOT EXISTS tier_label text, ADD COLUMN IF NOT EXISTS required_approvals integer NOT NULL DEFAULT 1, ADD COLUMN IF NOT EXISTS approvals_count integer NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS screening_state text NOT NULL DEFAULT 'PENDING', ADD COLUMN IF NOT EXISTS screened_at timestamptz, ADD COLUMN IF NOT EXISTS sla_due_at timestamptz, ADD COLUMN IF NOT EXISTS hold_reason text, ADD COLUMN IF NOT EXISTS requires_dual_release boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS released_by uuid, ADD COLUMN IF NOT EXISTS released_at timestamptz;
CREATE TABLE IF NOT EXISTS public.refund_requests ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dispute_id uuid REFERENCES public.payment_disputes(id) ON DELETE SET NULL, transaction_id uuid NOT NULL, provider text NOT NULL DEFAULT 'MPESA', amount_cents bigint NOT NULL CHECK (amount_cents > 0), currency text NOT NULL DEFAULT 'KES', reason text NOT NULL, status text NOT NULL DEFAULT 'PENDING_APPROVAL' CHECK (status IN ('PENDING_APPROVAL','APPROVED','REJECTED','EXECUTING','EXECUTED','FAILED','CANCELLED')), requested_by uuid NOT NULL, approved_by uuid, approval_note text, rejected_reason text, execution_ref text, failure_reason text, idempotency_key text UNIQUE, executed_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.rental_bookings ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_reference text NOT NULL UNIQUE, quote_id uuid NOT NULL UNIQUE REFERENCES public.rental_quote_requests(id) ON DELETE RESTRICT, unit_id uuid REFERENCES public.rental_fleet_units(id) ON DELETE SET NULL, category text NOT NULL, asset_class text NOT NULL, band_label text NOT NULL, start_date date NOT NULL, end_date date NOT NULL, pickup_location text NOT NULL, contact_name text NOT NULL, contact_email text NOT NULL, contact_phone text NOT NULL, company_name text, rider_user_id uuid, total_kes numeric(14,2) NOT NULL, amount_paid_kes numeric(14,2) NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'KES', mpesa_receipt text, status text NOT NULL DEFAULT 'CONFIRMED' CHECK (status IN ('CONFIRMED','AWAITING_ALLOCATION','PICKED_UP','RETURNED','CANCELLED')), picked_up_at timestamptz, returned_at timestamptz, change_request text CHECK (change_request IN ('RESCHEDULE','CANCELLATION')), change_requested_at timestamptz, requested_start_date date, requested_end_date date, change_reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (end_date >= start_date) );
ALTER TABLE public.rental_bookings ADD COLUMN IF NOT EXISTS correlation_id uuid;
ALTER TABLE public.rental_bookings ADD COLUMN IF NOT EXISTS provider_id uuid;
CREATE TABLE IF NOT EXISTS public.revenue_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_type public.revenue_event_type NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), source_ref text, driver_id uuid, rider_id uuid, corporate_id uuid, gross_amount_cents bigint NOT NULL CHECK (gross_amount_cents > 0), currency text NOT NULL DEFAULT 'KES', journal_id uuid REFERENCES public.journals(id), recognized_at timestamptz, status text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','RECOGNIZED','REVERSED')), metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.sales_leads ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_ref text NOT NULL UNIQUE, sales_staff_id uuid NOT NULL REFERENCES public.staff_members(id) ON DELETE RESTRICT, created_by uuid NOT NULL, organisation_name text NOT NULL, contact_name text NOT NULL, contact_email text, contact_phone text, service_interest text NOT NULL, origin_label text, destination_label text, service_date date, estimated_value_kes numeric(14,2), currency text NOT NULL DEFAULT 'KES', stage text NOT NULL DEFAULT 'NEW', qualification_notes text, lost_reason text, opportunity_id uuid REFERENCES public.commercial_opportunities(id) ON DELETE SET NULL, order_id uuid, booking_ref text, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT sales_leads_stage_chk CHECK (stage IN ('NEW','QUALIFIED','OPPORTUNITY','QUOTED','ACCEPTED','BOOKED','FULFILLED','CLOSED_WON','CLOSED_LOST','DISQUALIFIED')) );
ALTER TABLE public.sales_leads ADD COLUMN IF NOT EXISTS source text NOT NULL DEFAULT 'staff_capture', ADD COLUMN IF NOT EXISTS submitted_by_user_id uuid, ADD COLUMN IF NOT EXISTS account_id uuid, ADD COLUMN IF NOT EXISTS information_request text, ADD COLUMN IF NOT EXISTS closed_at timestamptz;
ALTER TABLE public.sales_leads ADD COLUMN IF NOT EXISTS qualified_at timestamptz, ADD COLUMN IF NOT EXISTS proposal_sent_at timestamptz, ADD COLUMN IF NOT EXISTS is_test boolean NOT NULL DEFAULT false;
ALTER TABLE public.sales_leads ADD COLUMN IF NOT EXISTS contact_state text NOT NULL DEFAULT 'NOT_CONTACTED', ADD COLUMN IF NOT EXISTS last_outreach_at timestamptz, ADD COLUMN IF NOT EXISTS first_reply_at timestamptz, ADD COLUMN IF NOT EXISTS last_reply_at timestamptz, ADD COLUMN IF NOT EXISTS contact_token text;
ALTER TABLE public.sales_leads ADD COLUMN IF NOT EXISTS first_outreach_at timestamptz;
ALTER TABLE public.sales_leads ADD COLUMN IF NOT EXISTS lost_reason_code text, ADD COLUMN IF NOT EXISTS waiting_on text, ADD COLUMN IF NOT EXISTS awaiting_item text, ADD COLUMN IF NOT EXISTS awaiting_due_date date, ADD COLUMN IF NOT EXISTS meeting_held_at timestamptz, ADD COLUMN IF NOT EXISTS quote_shared_at timestamptz, ADD COLUMN IF NOT EXISTS contract_shared_at timestamptz, ADD COLUMN IF NOT EXISTS contract_signed_at timestamptz, ADD COLUMN IF NOT EXISTS won_revenue_kes numeric, ADD COLUMN IF NOT EXISTS import_batch_id uuid;
ALTER TABLE public.sales_leads ADD COLUMN IF NOT EXISTS lost_competitor text, ADD COLUMN IF NOT EXISTS lost_expected_price_kes numeric, ADD COLUMN IF NOT EXISTS lost_revisit_date date;
ALTER TABLE public.sales_leads ADD COLUMN IF NOT EXISTS partner_application_id uuid;
CREATE TABLE IF NOT EXISTS public.tax_exemptions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scheme_id uuid NOT NULL REFERENCES public.tax_schemes(id), subject_kind text NOT NULL CHECK (subject_kind IN ('user','corporate','category')), subject_id uuid, subject_code text, reason text NOT NULL, certificate_url text, effective_from date NOT NULL DEFAULT CURRENT_DATE, effective_to date, active boolean NOT NULL DEFAULT true, granted_by uuid REFERENCES auth.users(id), revoked_by uuid REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.tax_invoices ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_no text UNIQUE, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','pending_approval','approved','issued','sent','part_paid','paid','cancelled')), lead_id uuid, proforma_id uuid REFERENCES public.proforma_invoices(id) ON DELETE SET NULL, customer_company text NOT NULL DEFAULT '', customer_address text, customer_pin text, customer_contact_person text, customer_email text, customer_phone text, customer_ref text, quote_reference text, contract_reference text, lpo_reference text, service_from date, service_to date, payment_terms text NOT NULL DEFAULT 'Payment due within 14 days of invoice date', currency text NOT NULL DEFAULT 'KES', vat_rate numeric NOT NULL DEFAULT 16, vat_inclusive boolean NOT NULL DEFAULT false, issue_date date, due_date date, notes text, authorised_name text, authorised_title text, subtotal_cents bigint NOT NULL DEFAULT 0, vat_cents bigint NOT NULL DEFAULT 0, total_cents bigint NOT NULL DEFAULT 0, paid_cents bigint NOT NULL DEFAULT 0, owner_staff_id uuid, created_by uuid, submitted_at timestamptz, submitted_by uuid, approved_at timestamptz, approved_by uuid, approval_note text, sole_approver boolean NOT NULL DEFAULT false, issued_at timestamptz, sent_to text, sent_at timestamptz, pdf_sha256 text, cancel_reason text, is_test boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.tax_invoices ADD COLUMN IF NOT EXISTS account_id uuid, ADD COLUMN IF NOT EXISTS contract_id uuid;
CREATE TABLE IF NOT EXISTS public.tax_periods ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scheme_id uuid NOT NULL REFERENCES public.tax_schemes(id), jurisdiction text NOT NULL DEFAULT 'KE', period_start date NOT NULL, period_end date NOT NULL, cadence text NOT NULL CHECK (cadence IN ('MONTHLY','QUARTERLY','ANNUAL')), status public.tax_period_status NOT NULL DEFAULT 'OPEN', filed_at timestamptz, filed_by uuid REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (period_end >= period_start), UNIQUE (scheme_id, jurisdiction, period_start, period_end) );

CREATE TABLE IF NOT EXISTS public.tax_rates ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scheme_id uuid NOT NULL REFERENCES public.tax_schemes(id) ON DELETE RESTRICT, rate_bps int NOT NULL CHECK (rate_bps >= 0 AND rate_bps <= 10000), jurisdiction text NOT NULL DEFAULT 'KE', currency text NOT NULL DEFAULT 'KES', effective_from date NOT NULL, effective_to date, notes text, created_by uuid REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (effective_to IS NULL OR effective_to >= effective_from) );

CREATE TABLE IF NOT EXISTS public.tax_rules ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rule_code text NOT NULL, version int NOT NULL DEFAULT 1, scheme_id uuid NOT NULL REFERENCES public.tax_schemes(id), predicate jsonb NOT NULL DEFAULT '{}'::jsonb, priority int NOT NULL DEFAULT 100, active boolean NOT NULL DEFAULT true, effective_from date NOT NULL DEFAULT CURRENT_DATE, effective_to date, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (rule_code, version) );

CREATE TABLE IF NOT EXISTS public.treasury_accounts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, kind public.treasury_account_kind NOT NULL, currency text NOT NULL REFERENCES public.currencies(code) DEFAULT 'KES', provider text, external_ref text, ledger_account_id uuid REFERENCES public.ledger_accounts(id), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.budgets ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE CASCADE, cost_center_id uuid REFERENCES public.cost_centers(id) ON DELETE SET NULL, name text NOT NULL, period_start date NOT NULL, period_end date NOT NULL, total_cents bigint NOT NULL CHECK (total_cents >= 0), reserved_cents bigint NOT NULL DEFAULT 0, consumed_cents bigint NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'KES', status public.budget_status NOT NULL DEFAULT 'DRAFT', notes text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (period_end >= period_start) );

CREATE TABLE IF NOT EXISTS public.carrier_profiles ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid NOT NULL UNIQUE REFERENCES public.partners(id) ON DELETE CASCADE, carrier_code text NOT NULL UNIQUE, legal_entity_name text NOT NULL, operating_status public.carrier_operating_status NOT NULL DEFAULT 'ONBOARDING', service_categories text[] NOT NULL DEFAULT '{}', corridors text[] NOT NULL DEFAULT '{}', operating_countries text[] NOT NULL DEFAULT '{KE}', regions text[] NOT NULL DEFAULT '{}', ops_contact_name text, ops_contact_email text, ops_contact_phone text, finance_contact_name text, finance_contact_email text, payment_terms_days integer NOT NULL DEFAULT 30 CHECK (payment_terms_days BETWEEN 0 AND 180), settlement_currency text NOT NULL DEFAULT 'KES', commercial_terms jsonb NOT NULL DEFAULT '{}'::jsonb, tax_identifier text, contract_status public.carrier_contract_status NOT NULL DEFAULT 'NONE', contract_reference text, effective_from date, effective_until date, onboarding_notes text, created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (effective_until IS NULL OR effective_from IS NULL OR effective_until >= effective_from) );

CREATE TABLE IF NOT EXISTS public.charter_bookings ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference text NOT NULL UNIQUE, quote_id uuid REFERENCES public.charter_quotes(id) ON DELETE SET NULL, user_id uuid, category_slug text NOT NULL, asset_name text NOT NULL, passengers jsonb NOT NULL DEFAULT '[]'::jsonb, contact jsonb NOT NULL DEFAULT '{}'::jsonb, trip jsonb NOT NULL DEFAULT '{}'::jsonb, amount numeric NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'USD', payment_method text NOT NULL DEFAULT 'invoice' CHECK (payment_method IN ('invoice','mpesa','card','corporate_wallet')), payment_status text NOT NULL DEFAULT 'pending' CHECK (payment_status IN ('pending','authorized','paid','failed','refunded')), status text NOT NULL DEFAULT 'confirmed' CHECK (status IN ('pending','confirmed','in_progress','completed','cancelled')), flight_status text NOT NULL DEFAULT 'scheduled' CHECK (flight_status IN ('scheduled','crew_assigned','boarding','departed','en_route','landed','completed','cancelled')), flight_events jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.charter_bookings ADD COLUMN IF NOT EXISTS mpesa_receipt text, ADD COLUMN IF NOT EXISTS checkout_request_id text, ADD COLUMN IF NOT EXISTS paid_at timestamptz;
ALTER TABLE public.charter_bookings ADD COLUMN IF NOT EXISTS tax_cents bigint, ADD COLUMN IF NOT EXISTS commission_bps integer, ADD COLUMN IF NOT EXISTS commission_cents bigint, ADD COLUMN IF NOT EXISTS partner_entitlement_cents bigint, ADD COLUMN IF NOT EXISTS payment_provider text, ADD COLUMN IF NOT EXISTS payment_reference text, ADD COLUMN IF NOT EXISTS financials_source text, ADD COLUMN IF NOT EXISTS financials_captured_at timestamptz;
CREATE TABLE IF NOT EXISTS public.charter_wallet_finance_actions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), funding_request_id uuid REFERENCES public.charter_wallet_funding_requests(id) ON DELETE SET NULL, wallet_id uuid REFERENCES public.charter_corporate_wallets(id) ON DELETE CASCADE, action text NOT NULL, amount_kes numeric, reason text NOT NULL, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, ledger_entry_id uuid, actor_id uuid, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.charter_wallet_finance_alerts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), finding_id uuid NOT NULL UNIQUE REFERENCES public.charter_wallet_reconciliation_findings(id) ON DELETE CASCADE, run_id uuid REFERENCES public.charter_wallet_reconciliation_runs(id) ON DELETE CASCADE, severity text NOT NULL, kind text NOT NULL, detail text NOT NULL, wallet_id uuid, funding_request_id uuid, expected_kes numeric, actual_kes numeric, status text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, email_sent_to text[] NOT NULL DEFAULT '{}', webhook_status integer, last_error text, notified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.charter_wallet_finance_alerts ADD COLUMN IF NOT EXISTS next_attempt_at timestamptz DEFAULT now(), ADD COLUMN IF NOT EXISTS max_attempts integer NOT NULL DEFAULT 6, ADD COLUMN IF NOT EXISTS acknowledged_at timestamptz, ADD COLUMN IF NOT EXISTS acknowledged_by uuid, ADD COLUMN IF NOT EXISTS acknowledgement_notes text;
CREATE TABLE IF NOT EXISTS public.corporate_credit_facilities ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE RESTRICT, guarantee_id uuid NOT NULL REFERENCES public.corporate_bank_guarantees(id) ON DELETE RESTRICT, approved_credit_limit_cents bigint NOT NULL CHECK (approved_credit_limit_cents >= 0), risk_margin_bps integer NOT NULL DEFAULT 3000 CHECK (risk_margin_bps BETWEEN 0 AND 10000), utilized_credit_cents bigint NOT NULL DEFAULT 0 CHECK (utilized_credit_cents >= 0), currency text NOT NULL DEFAULT 'KES', effective_date date NOT NULL, expiry_date date NOT NULL, state public.credit_facility_state NOT NULL DEFAULT 'DRAFT', max_transaction_cents bigint, daily_exposure_cents bigint, monthly_exposure_cents bigint, policy_reference text, approved_by uuid, approved_at timestamptz, activated_by uuid, activated_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.corporate_invoices ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE RESTRICT, period_id uuid NOT NULL REFERENCES public.corporate_billing_periods(id) ON DELETE RESTRICT, invoice_number text NOT NULL UNIQUE, etims_invoice_id uuid REFERENCES public.etims_invoices(id), journal_id uuid REFERENCES public.journals(id), status public.corporate_invoice_status NOT NULL DEFAULT 'DRAFT', subtotal_cents bigint NOT NULL, tax_total_cents bigint NOT NULL, adjustments_cents bigint NOT NULL DEFAULT 0, total_cents bigint NOT NULL, paid_cents bigint NOT NULL DEFAULT 0, balance_cents bigint NOT NULL, currency text NOT NULL DEFAULT 'KES', issued_at timestamptz NOT NULL DEFAULT now(), due_at timestamptz NOT NULL, paid_at timestamptz, voided_at timestamptz, voided_reason text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (corporate_id, period_id) );

DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['driver_tax_liabilities','etims_invoice_items','exchange_rates','freight_consignments','freight_quotations','freight_requirements','ledger_entries','ledger_snapshots','logistics_manifests','logistics_routes','mpesa_callback_logs','mpesa_payment_flags','packages','partners','payment_alerts','payment_audit_logs_v2','payment_certification_baselines','payment_certification_scenarios','payment_chaos_runs','payment_continuous_qualification_reruns','payment_dead_letters','payment_infra_slo_measurements','payment_notification_dispatches','payment_projection_incidents','payment_projection_sync_runs','payment_qualification_evidence_packs','payment_qualification_step_traces','payment_replay_cert_divergences','payment_slo_measurements','proforma_invoice_events','proforma_invoice_lines','provider_invoice_lines','provider_payout_requests','refund_requests','rental_bookings','revenue_events','sales_leads','tax_exemptions','tax_invoices','tax_periods','tax_rates','tax_rules','treasury_accounts','budgets','carrier_profiles','charter_bookings','charter_wallet_finance_actions','charter_wallet_finance_alerts','corporate_credit_facilities','corporate_invoices'] LOOP EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t); EXECUTE format('GRANT ALL ON public.%I TO service_role', t); EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('CREATE POLICY "Admins manage restored records" ON public.%I FOR ALL TO authenticated USING (public.has_any_role(auth.uid(), ARRAY[''admin'',''super_admin'',''finance_admin'']::public.app_role[])) WITH CHECK (public.has_any_role(auth.uid(), ARRAY[''admin'',''super_admin'',''finance_admin'']::public.app_role[]))', t); END LOOP; END $$;CREATE TABLE IF NOT EXISTS public.driver_etims_invoices ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_number text NOT NULL UNIQUE, driver_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT, revenue_event_id uuid REFERENCES public.revenue_events(id), platform_invoice_id uuid REFERENCES public.etims_invoices(id), status public.driver_etims_invoice_status NOT NULL DEFAULT 'PENDING', gross_cents bigint NOT NULL, net_cents bigint NOT NULL, tax_cents bigint NOT NULL, tax_scheme_code text NOT NULL DEFAULT 'TOT', tax_rate_bps int NOT NULL, currency text NOT NULL DEFAULT 'KES', issued_at timestamptz NOT NULL DEFAULT now(), kra_invoice_no text, kra_qr_code text, attempt_count int NOT NULL DEFAULT 0, last_error text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.driver_finance_clearance_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), clearance_id uuid NOT NULL REFERENCES public.driver_finance_clearances(id) ON DELETE CASCADE, action text NOT NULL, state_from text, state_to text, note text, actor_user_id uuid, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.driver_payout_failures ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payout_id uuid NOT NULL REFERENCES public.driver_payouts(id) ON DELETE CASCADE, error_code text, error_message text NOT NULL, retry_count int NOT NULL DEFAULT 0, payload jsonb, occurred_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.driver_payout_reversals ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payout_id uuid NOT NULL REFERENCES public.driver_payouts(id) ON DELETE CASCADE, reason text NOT NULL, reversal_journal_id uuid REFERENCES public.journals(id), initiated_by uuid, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.driver_tax_payments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), liability_id uuid NOT NULL REFERENCES public.driver_tax_liabilities(id) ON DELETE RESTRICT, driver_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, amount_cents bigint NOT NULL CHECK (amount_cents > 0), paid_at timestamptz NOT NULL DEFAULT now(), reference text, journal_id uuid REFERENCES public.journals(id), metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.freight_rfqs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rfq_number text NOT NULL UNIQUE, requirement_id uuid NOT NULL REFERENCES public.freight_requirements(id) ON DELETE CASCADE, tenant_id uuid, sourcing_mode text NOT NULL DEFAULT 'MULTI' CHECK (sourcing_mode IN ('SINGLE','MULTI')), state public.tender_state NOT NULL DEFAULT 'DRAFT', policy_id uuid REFERENCES public.freight_tender_policies(id) ON DELETE SET NULL, title text NOT NULL, scope_notes text, currency text NOT NULL DEFAULT 'KES', target_budget numeric(14,2), response_deadline timestamptz NOT NULL, clarification_deadline timestamptz, opened_at timestamptz, issued_at timestamptz, evaluation_started_at timestamptz, awarded_at timestamptz, cancelled_at timestamptz, cancel_reason text, is_test boolean NOT NULL DEFAULT false, created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.fx_transactions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), journal_id uuid REFERENCES public.journals(id), from_currency text NOT NULL REFERENCES public.currencies(code), to_currency text NOT NULL REFERENCES public.currencies(code), from_amount_cents bigint NOT NULL CHECK (from_amount_cents > 0), to_amount_cents bigint NOT NULL CHECK (to_amount_cents > 0), rate_id uuid REFERENCES public.exchange_rates(id), rate_applied numeric(20,10) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid );

CREATE TABLE IF NOT EXISTS public.invoice_collection_actions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES public.tax_invoices(id) ON DELETE CASCADE, action_type text NOT NULL CHECK (action_type IN ('call','email','visit','reminder','promise_to_pay','escalation','legal','write_off_request')), status text NOT NULL DEFAULT 'open' CHECK (status IN ('open','done','cancelled')), due_on date NOT NULL DEFAULT current_date, note text, outcome text, promised_amount_cents bigint CHECK (promised_amount_cents IS NULL OR promised_amount_cents >= 0), promised_on date, owner_staff_id uuid REFERENCES public.staff_members(id), created_by uuid, closed_by uuid, closed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.logistics_order_legs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES public.delivery_orders(id) ON DELETE CASCADE, leg_no integer NOT NULL, leg_type text NOT NULL, status text NOT NULL DEFAULT 'PLANNED', origin_kind text NOT NULL DEFAULT 'ADDRESS', origin_hub_id uuid REFERENCES public.logistics_hubs(id), origin_label text NOT NULL, origin_lat numeric(10,6), origin_lng numeric(10,6), destination_kind text NOT NULL DEFAULT 'ADDRESS', destination_hub_id uuid REFERENCES public.logistics_hubs(id), destination_label text NOT NULL, destination_lat numeric(10,6), destination_lng numeric(10,6), route_id uuid REFERENCES public.logistics_routes(id), vehicle_id uuid, driver_id uuid, planned_departure timestamptz, planned_arrival timestamptz, actual_departure timestamptz, actual_arrival timestamptz, eta timestamptz, planned_distance_km numeric(10,2), actual_distance_km numeric(10,2), exception_open boolean NOT NULL DEFAULT false, correlation_id text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (order_id, leg_no), CONSTRAINT legs_leg_no_positive CHECK (leg_no > 0), CONSTRAINT legs_leg_type CHECK (leg_type IN ('FIRST_MILE','LINE_HAUL','CROSS_DOCK','FINAL_MILE','RETURN')), CONSTRAINT legs_status CHECK (status IN ( 'PLANNED','AWAITING_CAPACITY','ASSIGNED','ACCEPTED','EN_ROUTE_TO_PICKUP','AT_PICKUP','LOADING','LOADED', 'DEPARTED','IN_TRANSIT','ARRIVED','UNLOADING','COMPLETED','CANCELLED','FAILED' )), CONSTRAINT legs_origin_kind CHECK (origin_kind IN ('ADDRESS','HUB')), CONSTRAINT legs_destination_kind CHECK (destination_kind IN ('ADDRESS','HUB')), CONSTRAINT legs_origin_hub_present CHECK (origin_kind <> 'HUB' OR origin_hub_id IS NOT NULL), CONSTRAINT legs_destination_hub_present CHECK (destination_kind <> 'HUB' OR destination_hub_id IS NOT NULL), CONSTRAINT legs_timing_order CHECK (actual_arrival IS NULL OR actual_departure IS NULL OR actual_arrival >= actual_departure) );

CREATE TABLE IF NOT EXISTS public.logistics_route_versions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), route_id uuid NOT NULL REFERENCES public.logistics_routes(id) ON DELETE CASCADE, version_number integer NOT NULL, parent_version_id uuid REFERENCES public.logistics_route_versions(id) ON DELETE SET NULL, change_reason text, optimization_source text NOT NULL DEFAULT 'manual', manual_override boolean NOT NULL DEFAULT true, plan_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), superseded_at timestamptz, UNIQUE (route_id, version_number) );

CREATE TABLE IF NOT EXISTS public.offline_payment_attestations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id uuid NOT NULL REFERENCES public.commercial_transactions(id) ON DELETE RESTRICT, transaction_ref text NOT NULL, method text NOT NULL, reference text NOT NULL, amount_cents bigint NOT NULL, currency text NOT NULL DEFAULT 'KES', collected_at timestamptz NOT NULL DEFAULT now(), attested_by uuid, attested_by_identity text NOT NULL, attestation_note text, evidence_kind text NOT NULL DEFAULT 'operator_attestation', source text NOT NULL DEFAULT 'manual', created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.partner_customers ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid NOT NULL REFERENCES public.partners(id) ON DELETE CASCADE, full_name text NOT NULL, phone text, email text, customer_reference text, organisation text, preferences jsonb NOT NULL DEFAULT '{}'::jsonb, accessibility_needs text, lifetime_spend numeric(14,2) NOT NULL DEFAULT 0, outstanding_balance numeric(14,2) NOT NULL DEFAULT 0, is_demo boolean NOT NULL DEFAULT false, created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.partner_settlements ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), settlement_code text NOT NULL UNIQUE, partner_id uuid NOT NULL REFERENCES public.partners(id) ON DELETE CASCADE, period_start date NOT NULL, period_end date NOT NULL, status public.partner_settlement_state NOT NULL DEFAULT 'open', currency text NOT NULL DEFAULT 'KES', orders_count integer NOT NULL DEFAULT 0, gross_value numeric(14,2) NOT NULL DEFAULT 0, supplier_cost numeric(14,2) NOT NULL DEFAULT 0, yalla_margin numeric(14,2) NOT NULL DEFAULT 0, partner_margin numeric(14,2) NOT NULL DEFAULT 0, taxes numeric(14,2) NOT NULL DEFAULT 0, payout_amount numeric(14,2) NOT NULL DEFAULT 0, paid_amount numeric(14,2), variance_amount numeric(14,2), payment_reference text, notes text, generated_by uuid, approved_by uuid, approved_at timestamptz, paid_at timestamptz, reconciled_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT partner_settlements_period_chk CHECK (period_end >= period_start), CONSTRAINT partner_settlements_unique_period UNIQUE (partner_id, period_start, period_end) );

CREATE TABLE IF NOT EXISTS public.partner_wallets ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid NOT NULL UNIQUE REFERENCES public.partners(id) ON DELETE CASCADE, currency text NOT NULL DEFAULT 'KES', balance numeric(14,2) NOT NULL DEFAULT 0, reserved numeric(14,2) NOT NULL DEFAULT 0, credit_limit numeric(14,2) NOT NULL DEFAULT 0, low_balance_threshold numeric(14,2) NOT NULL DEFAULT 0, is_prefunded boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_certification_forensics ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scenario_id uuid NOT NULL UNIQUE REFERENCES public.payment_certification_scenarios(id) ON DELETE CASCADE, run_id uuid NOT NULL, scenario_key text NOT NULL, stage text NOT NULL, edge_function text, rpc_name text, db_mutation jsonb NOT NULL DEFAULT '{}'::jsonb, failure_class text NOT NULL, correlation_id uuid, trace_id text, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, recommended_fix text NOT NULL, classified_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_incident_group_members ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), group_id UUID NOT NULL REFERENCES public.payment_incident_groups(id) ON DELETE CASCADE, alert_id UUID NOT NULL REFERENCES public.payment_alerts(id) ON DELETE CASCADE, added_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (group_id, alert_id) );

CREATE TABLE IF NOT EXISTS public.payment_journey_validations ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, correlation_id UUID NOT NULL, scenario_id UUID REFERENCES public.payment_certification_scenarios(id) ON DELETE CASCADE, status TEXT NOT NULL, checks JSONB NOT NULL DEFAULT '[]'::jsonb, missing_stages TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], duplicate_events INT NOT NULL DEFAULT 0, orphan_transitions INT NOT NULL DEFAULT 0, callback_persisted BOOLEAN, ledger_ok BOOLEAN, settlement_ok BOOLEAN, notification_ok BOOLEAN, computed_at TIMESTAMPTZ NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payment_receipts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), receipt_no text UNIQUE, status text NOT NULL DEFAULT 'issued' CHECK (status IN ('issued','sent','void')), invoice_id uuid NOT NULL REFERENCES public.tax_invoices(id) ON DELETE RESTRICT, lead_id uuid, amount_cents bigint NOT NULL CHECK (amount_cents > 0), currency text NOT NULL DEFAULT 'KES', method text NOT NULL DEFAULT 'BANK_TRANSFER' CHECK (method IN ('MPESA','BANK_TRANSFER','CHEQUE','CASH','CARD','OTHER')), payment_reference text, received_on date NOT NULL DEFAULT current_date, received_from text, notes text, authorised_name text, authorised_title text, owner_staff_id uuid, created_by uuid, sent_to text, sent_at timestamptz, pdf_sha256 text, void_reason text, is_test boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.provider_payout_approvals ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.provider_payout_requests(id) ON DELETE CASCADE, level integer NOT NULL CHECK (level >= 1), actor_user_id uuid NOT NULL, note text, decided_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (request_id, level), UNIQUE (request_id, actor_user_id) );

CREATE TABLE IF NOT EXISTS public.provider_payout_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.provider_payout_requests(id) ON DELETE CASCADE, event_type text NOT NULL, state_from text, state_to text, note text, detail jsonb NOT NULL DEFAULT '{}'::jsonb, actor_user_id uuid, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.provider_payout_screening_results ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.provider_payout_requests(id) ON DELETE CASCADE, run_at timestamptz NOT NULL DEFAULT now(), check_key text NOT NULL, label text NOT NULL, result text NOT NULL CHECK (result = ANY (ARRAY['PASS','WARN','FAIL'])), detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.reconciliation_cases ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), reconciliation_id UUID REFERENCES public.corporate_financial_reconciliation(id) ON DELETE CASCADE, corp_reference TEXT NOT NULL, corporate_id UUID REFERENCES public.corporate_accounts(id) ON DELETE SET NULL, case_number TEXT UNIQUE NOT NULL DEFAULT ('CASE-' || lpad(nextval('public.reconciliation_case_seq')::text, 8, '0')), severity public.reconciliation_severity NOT NULL DEFAULT 'MEDIUM', status public.reconciliation_case_status NOT NULL DEFAULT 'OPEN', assigned_to UUID REFERENCES auth.users(id) ON DELETE SET NULL, created_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, notes TEXT, escalation_level INTEGER NOT NULL DEFAULT 0, resolution_notes TEXT, resolved_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, resolved_at TIMESTAMPTZ, reversed BOOLEAN NOT NULL DEFAULT FALSE, reversed_at TIMESTAMPTZ, reversed_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.refund_request_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), refund_request_id uuid NOT NULL REFERENCES public.refund_requests(id) ON DELETE CASCADE, actor_user_id uuid, action text NOT NULL, from_status text, to_status text, note text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.rental_ledger_entries ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entry_type text NOT NULL CHECK (entry_type IN ('CHARGE','PAYMENT','REFUND','DEPOSIT_HELD','DEPOSIT_RELEASED', 'FEE','PROVIDER_PAYABLE','COMMISSION','ADJUSTMENT','REVERSAL')), booking_id uuid REFERENCES public.rental_bookings(id) ON DELETE RESTRICT, quote_id uuid REFERENCES public.rental_quote_requests(id) ON DELETE RESTRICT, correlation_id uuid, source_ref text NOT NULL, memo text, currency text NOT NULL DEFAULT 'KES', posted_at timestamptz NOT NULL DEFAULT now(), posted_by uuid, UNIQUE (entry_type, source_ref) );

CREATE TABLE IF NOT EXISTS public.rental_refunds ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES public.rental_bookings(id) ON DELETE RESTRICT, correlation_id uuid, amount_kes numeric(14,2), reason text NOT NULL, state text NOT NULL DEFAULT 'REQUESTED' CHECK (state IN ('REQUESTED','POLICY_REQUIRED','AUTHORISED','PAID','DECLINED','FAILED')), policy_basis text, requested_by uuid, authorised_by uuid, authorised_at timestamptz, paid_reference text, paid_at timestamptz, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.settlement_batches ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL, batch_ref text NOT NULL, cutoff_at timestamptz NOT NULL, total_count int NOT NULL DEFAULT 0, total_amount_cents bigint NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'KES', status public.settlement_batch_status NOT NULL DEFAULT 'OPEN', treasury_account_id uuid REFERENCES public.treasury_accounts(id), created_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz, UNIQUE (provider, batch_ref) );

CREATE TABLE IF NOT EXISTS public.settlement_obligations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id uuid NOT NULL REFERENCES public.commercial_transactions(id) ON DELETE CASCADE, provider_kind text NOT NULL DEFAULT 'driver', provider_ref text, driver_id uuid, entitlement_cents bigint NOT NULL, currency text NOT NULL DEFAULT 'KES', calculation jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'calculated', payable_at timestamptz, payout_id uuid, paid_cents bigint, paid_at timestamptz, reconciled_at timestamptz, variance_cents bigint, variance_reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT settlement_obligations_status_check CHECK (status = ANY (ARRAY['calculated','payable','paid','reconciled','variance','disputed','void'])), CONSTRAINT settlement_obligations_transaction_unique UNIQUE (transaction_id, provider_ref) );

CREATE TABLE IF NOT EXISTS public.tax_calculations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scheme_id uuid NOT NULL REFERENCES public.tax_schemes(id), rate_id uuid NOT NULL REFERENCES public.tax_rates(id), source_kind text NOT NULL, source_id uuid, subject_user_id uuid, amount_cents bigint NOT NULL, tax_cents bigint NOT NULL, total_cents bigint NOT NULL, currency text NOT NULL DEFAULT 'KES', inputs jsonb NOT NULL DEFAULT '{}'::jsonb, rate_snapshot jsonb NOT NULL, calculated_at timestamptz NOT NULL DEFAULT now(), calculated_by uuid );

CREATE TABLE IF NOT EXISTS public.tax_invoice_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES public.tax_invoices(id) ON DELETE CASCADE, event text NOT NULL, status_before text, status_after text, actor_id uuid, note text, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.tax_invoice_lines ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES public.tax_invoices(id) ON DELETE CASCADE, line_no integer NOT NULL DEFAULT 1, description text NOT NULL DEFAULT '', service_date date, vehicle_category text, qty numeric NOT NULL DEFAULT 1, unit_rate_cents bigint NOT NULL DEFAULT 0, amount_cents bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.tax_reconciliations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), period_id uuid NOT NULL REFERENCES public.tax_periods(id), scheme_id uuid NOT NULL REFERENCES public.tax_schemes(id), ledger_total_cents bigint NOT NULL DEFAULT 0, etims_total_cents bigint NOT NULL DEFAULT 0, kra_total_cents bigint NOT NULL DEFAULT 0, variance_cents bigint NOT NULL DEFAULT 0, status public.tax_reconciliation_status NOT NULL DEFAULT 'OK', details jsonb NOT NULL DEFAULT '{}'::jsonb, run_by uuid, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.tax_submissions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), period_id uuid NOT NULL REFERENCES public.tax_periods(id), scheme_id uuid NOT NULL REFERENCES public.tax_schemes(id), submission_type text NOT NULL, status public.tax_submission_status NOT NULL DEFAULT 'DRAFT', total_taxable_cents bigint NOT NULL DEFAULT 0, total_tax_cents bigint NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'KES', payload jsonb NOT NULL DEFAULT '{}'::jsonb, kra_reference text, kra_response jsonb, submitted_at timestamptz, acknowledged_at timestamptz, submitted_by uuid, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (period_id, scheme_id, submission_type) );

CREATE TABLE IF NOT EXISTS public.budget_reservations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), budget_id uuid NOT NULL REFERENCES public.budgets(id) ON DELETE CASCADE, amount_cents bigint NOT NULL CHECK (amount_cents > 0), currency text NOT NULL DEFAULT 'KES', status public.budget_reservation_status NOT NULL DEFAULT 'RESERVED', reference text, approval_request_id uuid, reserved_by uuid, expires_at timestamptz, released_at timestamptz, consumed_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.carrier_capacity_slots ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), carrier_id uuid NOT NULL REFERENCES public.carrier_profiles(id) ON DELETE CASCADE, slot_reference text NOT NULL UNIQUE, vehicle_id uuid REFERENCES public.vehicles(id) ON DELETE SET NULL, vehicle_type text NOT NULL, vehicle_class text, equipment text[] NOT NULL DEFAULT '{}', origin_area_code text, destination_area_code text, corridor text, exclusive_vehicle boolean NOT NULL DEFAULT false, offered_kg numeric(12,2) NOT NULL CHECK (offered_kg > 0), offered_cbm numeric(12,3), reserved_kg numeric(12,2) NOT NULL DEFAULT 0 CHECK (reserved_kg >= 0), committed_kg numeric(12,2) NOT NULL DEFAULT 0 CHECK (committed_kg >= 0), consumed_kg numeric(12,2) NOT NULL DEFAULT 0 CHECK (consumed_kg >= 0), availability_status public.capacity_availability_state NOT NULL DEFAULT 'CONFIGURED', effective_from timestamptz NOT NULL, effective_until timestamptz NOT NULL, notes text, created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (effective_until > effective_from), CONSTRAINT ccs_no_overbooking CHECK (reserved_kg + committed_kg + consumed_kg <= offered_kg) );

CREATE TABLE IF NOT EXISTS public.carrier_contracts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contract_number text NOT NULL UNIQUE, carrier_id uuid NOT NULL REFERENCES public.carrier_profiles(id) ON DELETE CASCADE, contract_type text NOT NULL DEFAULT 'FRAMEWORK' CHECK (contract_type IN ('FRAMEWORK','SPOT','DEDICATED','SEASONAL')), status public.carrier_contract_status NOT NULL DEFAULT 'DRAFT', currency text NOT NULL DEFAULT 'KES', payment_terms_days integer NOT NULL DEFAULT 30, effective_from date NOT NULL, effective_until date, document_id uuid, signed_by_carrier_at timestamptz, signed_by_yalla_at timestamptz, signed_by uuid, termination_notice_days integer NOT NULL DEFAULT 30, created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (effective_until IS NULL OR effective_until >= effective_from) );

CREATE TABLE IF NOT EXISTS public.carrier_settlement_destinations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), carrier_id uuid NOT NULL REFERENCES public.carrier_profiles(id) ON DELETE CASCADE, destination_type text NOT NULL CHECK (destination_type IN ('MPESA','BANK')), account_name text NOT NULL, msisdn text, bank_name text, bank_branch text, bank_account_number text, currency text NOT NULL DEFAULT 'KES', is_default boolean NOT NULL DEFAULT false, verification_state text NOT NULL DEFAULT 'UNVERIFIED' CHECK (verification_state IN ('UNVERIFIED','UNDER_REVIEW','VERIFIED','REJECTED','SUSPENDED')), verified_by uuid, verified_at timestamptz, verification_notes text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT carrier_dest_shape CHECK ( (destination_type = 'MPESA' AND msisdn IS NOT NULL) OR (destination_type = 'BANK' AND bank_name IS NOT NULL AND bank_account_number IS NOT NULL) ) );

CREATE TABLE IF NOT EXISTS public.charter_payment_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid REFERENCES public.charter_bookings(id) ON DELETE SET NULL, reference text, checkout_request_id text NOT NULL, dedupe_key text NOT NULL UNIQUE, result_code integer, result_desc text, mpesa_receipt text, amount_kes numeric, applied_status text NOT NULL, outcome text NOT NULL DEFAULT 'applied', payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.charter_wallet_alert_delivery_attempts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), alert_id uuid NOT NULL REFERENCES public.charter_wallet_finance_alerts(id) ON DELETE CASCADE, attempt integer NOT NULL, channel text NOT NULL, target text, ok boolean NOT NULL DEFAULT false, status_code integer, error text, duration_ms integer, next_attempt_at timestamptz, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.charter_wallet_ledger ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), wallet_id uuid NOT NULL REFERENCES public.charter_corporate_wallets(id) ON DELETE CASCADE, direction text NOT NULL, amount_kes numeric NOT NULL, balance_after numeric NOT NULL, reference text, booking_id uuid REFERENCES public.charter_bookings(id) ON DELETE SET NULL, approver_name text, approver_title text, cost_center text, prev_hash text, entry_hash text NOT NULL, actor_id uuid, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.corporate_credit_reservations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL, facility_id uuid NOT NULL REFERENCES public.corporate_credit_facilities(id) ON DELETE RESTRICT, guarantee_id uuid NOT NULL REFERENCES public.corporate_bank_guarantees(id) ON DELETE RESTRICT, amount_cents bigint NOT NULL CHECK (amount_cents > 0), final_amount_cents bigint, currency text NOT NULL DEFAULT 'KES', state public.credit_reservation_state NOT NULL DEFAULT 'ACTIVE', idempotency_key text NOT NULL, booking_id uuid, trip_request_id uuid, requested_by uuid, correlation_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), released_at timestamptz, utilized_at timestamptz, UNIQUE (corporate_id, idempotency_key) );

CREATE TABLE IF NOT EXISTS public.corporate_invoice_adjustments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES public.corporate_invoices(id) ON DELETE RESTRICT, kind text NOT NULL CHECK (kind IN ('CREDIT','DEBIT','WRITE_OFF','DISCOUNT')), amount_cents bigint NOT NULL, reason text NOT NULL, applied_by uuid, journal_id uuid REFERENCES public.journals(id), metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.corporate_invoice_items ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES public.corporate_invoices(id) ON DELETE RESTRICT, line_number integer NOT NULL, revenue_event_id uuid REFERENCES public.revenue_events(id), source_ref text, description text NOT NULL, employee_user_id uuid, employee_name text, department text, cost_center text, policy_code text, trip_origin text, trip_destination text, trip_started_at timestamptz, trip_ended_at timestamptz, quantity numeric NOT NULL DEFAULT 1, unit_price_cents bigint NOT NULL, taxable_cents bigint NOT NULL, tax_cents bigint NOT NULL, total_cents bigint NOT NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (invoice_id, line_number) );

CREATE TABLE IF NOT EXISTS public.corporate_invoice_taxes ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES public.corporate_invoices(id) ON DELETE RESTRICT, tax_scheme_code text NOT NULL, tax_rate_bps integer NOT NULL, taxable_cents bigint NOT NULL, tax_cents bigint NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (invoice_id, tax_scheme_code, tax_rate_bps) );

CREATE TABLE IF NOT EXISTS public.fin_payment_reports ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_ref text NOT NULL, charter_booking_id uuid REFERENCES public.charter_bookings(id) ON DELETE SET NULL, amount numeric(14,2) NOT NULL CHECK (amount > 0 AND amount < 100000000), currency text NOT NULL DEFAULT 'KES', paid_on date NOT NULL, method text NOT NULL DEFAULT 'mpesa' CHECK (method IN ('mpesa','bank','cash','card','other')), payment_reference text, note text CHECK (char_length(note) <= 1000), source text NOT NULL CHECK (source IN ('client','team','email','mpesa')), status text NOT NULL DEFAULT 'reported' CHECK (status IN ('reported','verified','rejected')), reported_by uuid, source_message_id uuid UNIQUE, verified_by uuid, verified_at timestamptz, decision_note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.freight_invoices ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_number text NOT NULL UNIQUE, party public.freight_charge_party NOT NULL DEFAULT 'CUSTOMER', status public.freight_invoice_status NOT NULL DEFAULT 'DRAFT', customer_user_id uuid, corporate_account_id uuid, carrier_id uuid REFERENCES public.carrier_profiles(id), currency text NOT NULL DEFAULT 'KES', subtotal numeric(14,2) NOT NULL DEFAULT 0, tax_total numeric(14,2) NOT NULL DEFAULT 0, total numeric(14,2) NOT NULL DEFAULT 0, paid_total numeric(14,2) NOT NULL DEFAULT 0, period_start date, period_end date, issued_at timestamptz, due_at timestamptz, voided_at timestamptz, void_reason text, correlation_id uuid NOT NULL DEFAULT gen_random_uuid(), idempotency_key text UNIQUE, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.journeys ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), journey_code text NOT NULL UNIQUE DEFAULT ('JNY-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))), partner_id uuid NOT NULL REFERENCES public.partners(id) ON DELETE CASCADE, partner_customer_id uuid REFERENCES public.partner_customers(id) ON DELETE SET NULL, title text NOT NULL, status text NOT NULL DEFAULT 'draft', starts_on date, ends_on date, passengers integer NOT NULL DEFAULT 1, supplier_cost_total numeric(14,2) NOT NULL DEFAULT 0, partner_margin_total numeric(14,2) NOT NULL DEFAULT 0, customer_price_total numeric(14,2) NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'KES', is_demo boolean NOT NULL DEFAULT false, created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.logistics_dispatch_requests ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_number text NOT NULL UNIQUE, order_id uuid NOT NULL REFERENCES public.delivery_orders(id) ON DELETE CASCADE, consignment_id uuid REFERENCES public.freight_consignments(id) ON DELETE SET NULL, leg_id uuid REFERENCES public.logistics_order_legs(id) ON DELETE SET NULL, quote_id uuid REFERENCES public.freight_quotations(id) ON DELETE SET NULL, customer_id uuid NOT NULL, origin_label text NOT NULL, origin_lat numeric(9,6), origin_lng numeric(9,6), destination_label text NOT NULL, destination_lat numeric(9,6), destination_lng numeric(9,6), pickup_window_start timestamptz, pickup_window_end timestamptz, delivery_window_start timestamptz, delivery_window_end timestamptz, vehicle_class text NOT NULL, required_payload_kg numeric(12,2) NOT NULL, required_volume_cbm numeric(12,3) NOT NULL DEFAULT 0, hazardous boolean NOT NULL DEFAULT false, temperature_controlled boolean NOT NULL DEFAULT false, special_requirements text[] NOT NULL DEFAULT '{}', priority integer NOT NULL DEFAULT 5, status text NOT NULL DEFAULT 'REQUESTED', matching_status text NOT NULL DEFAULT 'PENDING', assigned_vehicle_id uuid REFERENCES public.vehicles(id), assigned_driver_id uuid REFERENCES public.drivers(id), reservation_id uuid, last_failure_code text, last_failure_message text, idempotency_key text UNIQUE, correlation_id text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT dr_class CHECK (vehicle_class = ANY (ARRAY['TRUCK_3T','TRUCK_7T','TRUCK_14T','TRUCK_28T'])), CONSTRAINT dr_payload CHECK (required_payload_kg > 0), CONSTRAINT dr_priority CHECK (priority BETWEEN 1 AND 9), CONSTRAINT dr_status CHECK (status = ANY (ARRAY[ 'REQUESTED','MATCHING','MATCHED','RESERVED','BOOKED','DRIVER_PENDING','DRIVER_ACCEPTED', 'READY_FOR_PICKUP','EN_ROUTE_TO_PICKUP','ARRIVED_PICKUP','LOADING','LOADED','IN_TRANSIT', 'WAITLISTED','EXCEPTION','CANCELLED'])), CONSTRAINT dr_matching CHECK (matching_status = ANY (ARRAY['PENDING','RUNNING','MATCHED','NO_CAPACITY','REMATCH_REQUIRED','MANUAL_REVIEW'])) );
ALTER TABLE public.logistics_dispatch_requests ADD COLUMN IF NOT EXISTS request_kind text NOT NULL DEFAULT 'AD_HOC', ADD COLUMN IF NOT EXISTS route_instance_id uuid, ALTER COLUMN order_id DROP NOT NULL;
CREATE TABLE IF NOT EXISTS public.payment_receipt_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), receipt_id uuid NOT NULL REFERENCES public.payment_receipts(id) ON DELETE CASCADE, event text NOT NULL, status_before text, status_after text, actor_id uuid, note text, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.rental_ledger_lines ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entry_id uuid NOT NULL REFERENCES public.rental_ledger_entries(id) ON DELETE CASCADE, account text NOT NULL REFERENCES public.rental_ledger_accounts(account), direction text NOT NULL CHECK (direction IN ('DEBIT','CREDIT')), amount_kes numeric(14,2) NOT NULL CHECK (amount_kes > 0), detail jsonb NOT NULL DEFAULT '{}'::jsonb );

CREATE TABLE IF NOT EXISTS public.settlement_reconciliation ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid NOT NULL REFERENCES public.settlement_batches(id) ON DELETE CASCADE, ran_at timestamptz NOT NULL DEFAULT now(), expected_count int NOT NULL, actual_count int NOT NULL, expected_amount_cents bigint NOT NULL, actual_amount_cents bigint NOT NULL, variance_cents bigint NOT NULL, status text NOT NULL CHECK (status IN ('OK','VARIANCE','FAILED')), details jsonb NOT NULL DEFAULT '{}'::jsonb );

CREATE TABLE IF NOT EXISTS public.settlements ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid NOT NULL REFERENCES public.settlement_batches(id) ON DELETE CASCADE, transaction_id uuid REFERENCES public.mpesa_transactions(id), provider_ref text, amount_cents bigint NOT NULL CHECK (amount_cents > 0), currency text NOT NULL DEFAULT 'KES', status public.settlement_status NOT NULL DEFAULT 'PENDING', variance_cents bigint NOT NULL DEFAULT 0, notes text, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.tax_adjustments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), calculation_id uuid REFERENCES public.tax_calculations(id), period_id uuid REFERENCES public.tax_periods(id), scheme_id uuid NOT NULL REFERENCES public.tax_schemes(id), delta_cents bigint NOT NULL, currency text NOT NULL DEFAULT 'KES', reason text NOT NULL, approved_by uuid REFERENCES auth.users(id), journal_id uuid REFERENCES public.journals(id), created_by uuid REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.transaction_taxes ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), calculation_id uuid NOT NULL REFERENCES public.tax_calculations(id), mpesa_transaction_id uuid REFERENCES public.mpesa_transactions(id), wallet_transaction_id uuid REFERENCES public.wallet_transactions(id), journal_id uuid REFERENCES public.journals(id), scheme_code text NOT NULL, tax_cents bigint NOT NULL, currency text NOT NULL DEFAULT 'KES', created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.wallet_freezes ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), wallet_id UUID, corporate_id UUID REFERENCES public.corporate_accounts(id) ON DELETE CASCADE, reconciliation_id UUID REFERENCES public.corporate_financial_reconciliation(id) ON DELETE SET NULL, case_id UUID REFERENCES public.reconciliation_cases(id) ON DELETE SET NULL, reason TEXT NOT NULL, freeze_type TEXT NOT NULL DEFAULT 'WITHDRAWAL_ONLY' CHECK (freeze_type IN ('FULL','PARTIAL','WITHDRAWAL_ONLY','TOPUP_ONLY')), initiated_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, initiated_by_system BOOLEAN NOT NULL DEFAULT false, active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), released_at TIMESTAMPTZ, released_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, release_reason TEXT );

CREATE TABLE IF NOT EXISTS public.approval_requests ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE CASCADE, workflow_id uuid NOT NULL REFERENCES public.approval_workflows(id), cost_center_id uuid REFERENCES public.cost_centers(id), budget_id uuid REFERENCES public.budgets(id), reservation_id uuid REFERENCES public.budget_reservations(id), requested_by uuid NOT NULL, amount_cents bigint NOT NULL CHECK (amount_cents > 0), currency text NOT NULL DEFAULT 'KES', current_step int NOT NULL DEFAULT 1, status public.approval_request_status NOT NULL DEFAULT 'PENDING', reference text, justification text, due_at timestamptz, resolved_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.budget_consumption ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), budget_id uuid NOT NULL REFERENCES public.budgets(id) ON DELETE CASCADE, reservation_id uuid REFERENCES public.budget_reservations(id), amount_cents bigint NOT NULL CHECK (amount_cents > 0), currency text NOT NULL DEFAULT 'KES', journal_id uuid REFERENCES public.journals(id), corporate_invoice_id uuid REFERENCES public.corporate_invoices(id), consumed_at timestamptz NOT NULL DEFAULT now(), metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.capacity_reservations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reservation_reference text NOT NULL UNIQUE, slot_id uuid NOT NULL REFERENCES public.carrier_capacity_slots(id) ON DELETE CASCADE, carrier_id uuid NOT NULL REFERENCES public.carrier_profiles(id) ON DELETE CASCADE, tenant_id uuid, requirement_id uuid, award_id uuid, booking_id uuid, qty_kg numeric(12,2) NOT NULL CHECK (qty_kg > 0), qty_cbm numeric(12,3), state public.capacity_reservation_state NOT NULL DEFAULT 'ACTIVE', expires_at timestamptz NOT NULL, released_at timestamptz, released_reason text, idempotency_key text UNIQUE, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.carrier_capacity_ledger ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slot_id uuid NOT NULL REFERENCES public.carrier_capacity_slots(id) ON DELETE CASCADE, reservation_id uuid, entry_type text NOT NULL CHECK (entry_type IN ('OFFER','RESERVE','RELEASE','COMMIT','CONSUME','EXPIRE','ADJUST')), qty_kg numeric(12,2) NOT NULL, balance_after_kg numeric(12,2) NOT NULL, reason text, actor_id uuid, actor_role text NOT NULL DEFAULT 'system', idempotency_key text UNIQUE, correlation_id text, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.carrier_pod_submissions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), submission_reference text NOT NULL UNIQUE, carrier_id uuid NOT NULL REFERENCES public.carrier_profiles(id) ON DELETE RESTRICT, leg_id uuid NOT NULL REFERENCES public.logistics_order_legs(id) ON DELETE RESTRICT, order_id uuid NOT NULL, dispatch_request_id uuid REFERENCES public.logistics_dispatch_requests(id), recipient_name text NOT NULL, recipient_relationship text, recipient_id_reference text, recipient_phone text, delivered_at timestamptz NOT NULL, captured_lat numeric(10,6), captured_lng numeric(10,6), notes text, evidence jsonb NOT NULL DEFAULT '[]'::jsonb, integrity_hash text NOT NULL, state text NOT NULL DEFAULT 'SUBMITTED' CHECK (state IN ('SUBMITTED','APPROVED','REJECTED')), submitted_by uuid, submitted_at timestamptz NOT NULL DEFAULT now(), reviewed_by uuid, reviewed_at timestamptz, review_notes text, rejection_reason text, idempotency_key text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.carrier_quotations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), quote_number text NOT NULL UNIQUE, rfq_id uuid NOT NULL REFERENCES public.freight_rfqs(id) ON DELETE CASCADE, carrier_id uuid NOT NULL REFERENCES public.carrier_profiles(id) ON DELETE CASCADE, version integer NOT NULL DEFAULT 1 CHECK (version >= 1), supersedes_id uuid REFERENCES public.carrier_quotations(id) ON DELETE SET NULL, state public.carrier_quote_state NOT NULL DEFAULT 'DRAFT', currency text NOT NULL DEFAULT 'KES', pricing_basis public.freight_pricing_basis NOT NULL DEFAULT 'PER_SHIPMENT', rate_card_version_id uuid, base_freight numeric(14,2) NOT NULL DEFAULT 0 CHECK (base_freight >= 0), fuel_surcharge numeric(14,2) NOT NULL DEFAULT 0 CHECK (fuel_surcharge >= 0), waiting_charge numeric(14,2) NOT NULL DEFAULT 0 CHECK (waiting_charge >= 0), toll_charge numeric(14,2) NOT NULL DEFAULT 0 CHECK (toll_charge >= 0), handling_charge numeric(14,2) NOT NULL DEFAULT 0 CHECK (handling_charge >= 0), storage_charge numeric(14,2) NOT NULL DEFAULT 0 CHECK (storage_charge >= 0), loading_charge numeric(14,2) NOT NULL DEFAULT 0 CHECK (loading_charge >= 0), protection_charge numeric(14,2) NOT NULL DEFAULT 0 CHECK (protection_charge >= 0), accessorials jsonb NOT NULL DEFAULT '[]'::jsonb, accessorial_total numeric(14,2) NOT NULL DEFAULT 0 CHECK (accessorial_total >= 0), discount numeric(14,2) NOT NULL DEFAULT 0 CHECK (discount >= 0), tax_amount numeric(14,2) NOT NULL DEFAULT 0 CHECK (tax_amount >= 0), subtotal numeric(14,2) NOT NULL DEFAULT 0, total numeric(14,2) NOT NULL DEFAULT 0 CHECK (total >= 0), capacity_offered_kg numeric(12,2) NOT NULL CHECK (capacity_offered_kg > 0), capacity_slot_id uuid REFERENCES public.carrier_capacity_slots(id) ON DELETE SET NULL, transit_time_hours numeric(8,2), pickup_eta timestamptz, delivery_eta timestamptz, sla_committed text, vehicle_type text, equipment text[] NOT NULL DEFAULT '{}', conditions text, valid_until timestamptz NOT NULL, submitted_at timestamptz, submitted_by uuid, accepted_at timestamptz, snapshot jsonb, snapshot_hash text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (rfq_id, carrier_id, version) );

CREATE TABLE IF NOT EXISTS public.carrier_rate_cards ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), carrier_id uuid NOT NULL REFERENCES public.carrier_profiles(id) ON DELETE CASCADE, contract_id uuid REFERENCES public.carrier_contracts(id) ON DELETE SET NULL, rate_card_code text NOT NULL, version integer NOT NULL DEFAULT 1 CHECK (version >= 1), status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','LIVE','SUPERSEDED','EXPIRED')), currency text NOT NULL DEFAULT 'KES', effective_from timestamptz NOT NULL, effective_until timestamptz, published_at timestamptz, published_by uuid, supersedes_id uuid REFERENCES public.carrier_rate_cards(id) ON DELETE SET NULL, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (carrier_id, rate_card_code, version) );

CREATE TABLE IF NOT EXISTS public.freight_carrier_settlements ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), settlement_number text NOT NULL UNIQUE, carrier_id uuid NOT NULL REFERENCES public.carrier_profiles(id), contract_id uuid REFERENCES public.carrier_contracts(id), status public.freight_settlement_status NOT NULL DEFAULT 'CALCULATED', currency text NOT NULL DEFAULT 'KES', period_start date NOT NULL, period_end date NOT NULL, gross_amount numeric(14,2) NOT NULL DEFAULT 0, adjustments_amount numeric(14,2) NOT NULL DEFAULT 0, tax_amount numeric(14,2) NOT NULL DEFAULT 0, net_payable numeric(14,2) NOT NULL DEFAULT 0, carrier_claimed_amount numeric(14,2), variance_amount numeric(14,2) NOT NULL DEFAULT 0, payout_reference text, paid_at timestamptz, approved_by uuid, approved_at timestamptz, reversed_at timestamptz, reversal_reason text, correlation_id uuid NOT NULL DEFAULT gen_random_uuid(), idempotency_key text UNIQUE, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['driver_etims_invoices','driver_finance_clearance_events','driver_payout_failures','driver_payout_reversals','driver_tax_payments','freight_rfqs','fx_transactions','invoice_collection_actions','logistics_order_legs','logistics_route_versions','offline_payment_attestations','partner_customers','partner_settlements','partner_wallets','payment_certification_forensics','payment_incident_group_members','payment_journey_validations','payment_receipts','provider_payout_approvals','provider_payout_events','provider_payout_screening_results','reconciliation_cases','refund_request_events','rental_ledger_entries','rental_refunds','settlement_batches','settlement_obligations','tax_calculations','tax_invoice_events','tax_invoice_lines','tax_reconciliations','tax_submissions','budget_reservations','carrier_capacity_slots','carrier_contracts','carrier_settlement_destinations','charter_payment_events','charter_wallet_alert_delivery_attempts','charter_wallet_ledger','corporate_credit_reservations','corporate_invoice_adjustments','corporate_invoice_items','corporate_invoice_taxes','fin_payment_reports','freight_invoices','journeys','logistics_dispatch_requests','payment_receipt_events','rental_ledger_lines','settlement_reconciliation','settlements','tax_adjustments','transaction_taxes','wallet_freezes','approval_requests','budget_consumption','capacity_reservations','carrier_capacity_ledger','carrier_pod_submissions','carrier_quotations','carrier_rate_cards','freight_carrier_settlements'] LOOP EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t); EXECUTE format('GRANT ALL ON public.%I TO service_role', t); EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('CREATE POLICY "Admins manage restored records" ON public.%I FOR ALL TO authenticated USING (public.has_any_role(auth.uid(), ARRAY[''admin'',''super_admin'',''finance_admin'']::public.app_role[])) WITH CHECK (public.has_any_role(auth.uid(), ARRAY[''admin'',''super_admin'',''finance_admin'']::public.app_role[]))', t); END LOOP; END $$;CREATE TABLE IF NOT EXISTS public.mobility_orders ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_code text NOT NULL UNIQUE DEFAULT ('MO-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))), partner_id uuid REFERENCES public.partners(id) ON DELETE SET NULL, partner_customer_id uuid REFERENCES public.partner_customers(id) ON DELETE SET NULL, journey_id uuid REFERENCES public.journeys(id) ON DELETE SET NULL, leg_index integer NOT NULL DEFAULT 1, service_type public.mobility_service_type NOT NULL DEFAULT 'RIDE', status public.mobility_order_status NOT NULL DEFAULT 'DRAFT', pickup_label text, destination_label text, stops jsonb NOT NULL DEFAULT '[]'::jsonb, scheduled_at timestamptz, passengers integer NOT NULL DEFAULT 1, vehicle_class text, service_level text, supplier_cost numeric(14,2) NOT NULL DEFAULT 0, yalla_margin numeric(14,2) NOT NULL DEFAULT 0, partner_margin numeric(14,2) NOT NULL DEFAULT 0, taxes numeric(14,2) NOT NULL DEFAULT 0, fees numeric(14,2) NOT NULL DEFAULT 0, customer_price numeric(14,2) NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'KES', idempotency_key text UNIQUE, special_requirements text, is_demo boolean NOT NULL DEFAULT false, created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.payout_disbursements ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), disbursement_reference text NOT NULL UNIQUE, beneficiary_type text NOT NULL CHECK (beneficiary_type IN ('DRIVER','FLEET_OWNER')), beneficiary_id uuid NOT NULL, carrier_id uuid REFERENCES public.carrier_profiles(id), partner_id uuid, source_kind text NOT NULL CHECK (source_kind IN ('carrier_withdrawal','driver_payout')), source_id uuid NOT NULL, destination_id uuid REFERENCES public.carrier_settlement_destinations(id), destination_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, msisdn text NOT NULL, amount numeric(14,2) NOT NULL CHECK (amount > 0), currency text NOT NULL DEFAULT 'KES', provider text NOT NULL DEFAULT 'MPESA_B2C', state text NOT NULL DEFAULT 'DRAFT' CHECK (state IN ('DRAFT','INITIATED','PROCESSING','SUCCESS','FAILED','UNKNOWN','REVERSED','CANCELLED')), provider_conversation_id text, provider_originator_conversation_id text, provider_transaction_id text, provider_response_code text, result_code text, result_desc text, payment_evidence jsonb, ledger_entry_id uuid, reversal_ledger_entry_id uuid, settlement_reference text, reconciliation_state text NOT NULL DEFAULT 'PENDING' CHECK (reconciliation_state IN ('PENDING','MATCHED','EXCEPTION','REVERSED')), reconciliation_detail jsonb, failure_reason text, idempotency_key text NOT NULL UNIQUE, initiated_by uuid, initiated_at timestamptz, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.ride_payment_intents ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference text NOT NULL UNIQUE, corporate_id uuid REFERENCES public.corporate_accounts(id), booking_id uuid, trip_request_id uuid, approval_id uuid, amount_cents bigint NOT NULL CHECK (amount_cents > 0), currency text NOT NULL DEFAULT 'KES', mode text NOT NULL CHECK (mode IN ('CASH','CREDIT')), state public.ride_payment_state NOT NULL DEFAULT 'AWAITING_PAYMENT', channel_id uuid REFERENCES public.yalla_payment_channels(id), decision text, decision_reasons text[] NOT NULL DEFAULT '{}', reservation_id uuid REFERENCES public.corporate_credit_reservations(id), receivable_id uuid, invoice_id uuid REFERENCES public.corporate_invoices(id), paid_amount_cents bigint NOT NULL DEFAULT 0, mpesa_receipt text, verified_at timestamptz, cancelled_at timestamptz, failure_reason text, correlation_id uuid NOT NULL DEFAULT gen_random_uuid(), created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.settlement_failures ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid REFERENCES public.settlement_batches(id) ON DELETE CASCADE, settlement_id uuid REFERENCES public.settlements(id) ON DELETE CASCADE, error_code text, error_message text NOT NULL, retry_count int NOT NULL DEFAULT 0, resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.approval_payment_links ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.approval_requests(id) ON DELETE CASCADE, revenue_event_id uuid REFERENCES public.revenue_events(id), corporate_invoice_id uuid REFERENCES public.corporate_invoices(id), journal_id uuid REFERENCES public.journals(id), consumption_id uuid REFERENCES public.budget_consumption(id), linked_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.carrier_payable_lines ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), line_reference text NOT NULL UNIQUE, carrier_id uuid NOT NULL REFERENCES public.carrier_profiles(id) ON DELETE RESTRICT, partner_id uuid NOT NULL, order_id uuid NOT NULL, leg_id uuid NOT NULL REFERENCES public.logistics_order_legs(id), pod_submission_id uuid NOT NULL UNIQUE REFERENCES public.carrier_pod_submissions(id) ON DELETE RESTRICT, currency text NOT NULL DEFAULT 'KES', gross_amount numeric(14,2) NOT NULL CHECK (gross_amount >= 0), commission_pct numeric(6,3) NOT NULL CHECK (commission_pct >= 0 AND commission_pct <= 100), platform_fee numeric(14,2) NOT NULL CHECK (platform_fee >= 0), net_payable numeric(14,2) NOT NULL CHECK (net_payable >= 0), basis jsonb NOT NULL DEFAULT '{}'::jsonb, state text NOT NULL DEFAULT 'ACCRUED' CHECK (state IN ('ACCRUED','RELEASED')), ledger_entry_id uuid, accrued_by uuid, accrued_at timestamptz NOT NULL DEFAULT now(), released_by uuid, released_at timestamptz, idempotency_key text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.carrier_rate_lines ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rate_card_id uuid NOT NULL REFERENCES public.carrier_rate_cards(id) ON DELETE CASCADE, line_no integer NOT NULL, corridor text, origin_area_code text, destination_area_code text, vehicle_class text, pricing_basis public.freight_pricing_basis NOT NULL, unit_rate numeric(14,4) NOT NULL CHECK (unit_rate >= 0), minimum_charge numeric(14,2) NOT NULL DEFAULT 0 CHECK (minimum_charge >= 0), included_units numeric(12,3), fuel_surcharge_pct numeric(6,3) NOT NULL DEFAULT 0, waiting_rate_per_hour numeric(12,2) NOT NULL DEFAULT 0, accessorials jsonb NOT NULL DEFAULT '[]'::jsonb, break_min numeric(12,3), break_max numeric(12,3), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (rate_card_id, line_no) );

CREATE TABLE IF NOT EXISTS public.freight_awards ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), award_number text NOT NULL UNIQUE, rfq_id uuid NOT NULL REFERENCES public.freight_rfqs(id) ON DELETE CASCADE, requirement_id uuid NOT NULL REFERENCES public.freight_requirements(id) ON DELETE CASCADE, quotation_id uuid NOT NULL UNIQUE REFERENCES public.carrier_quotations(id) ON DELETE RESTRICT, carrier_id uuid NOT NULL REFERENCES public.carrier_profiles(id) ON DELETE RESTRICT, reservation_id uuid REFERENCES public.capacity_reservations(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'AWARDED' CHECK (status IN ('AWARDED','CANCELLED','SUPERSEDED')), awarded_total numeric(14,2) NOT NULL CHECK (awarded_total >= 0), currency text NOT NULL DEFAULT 'KES', evaluation_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, award_justification text NOT NULL, lowest_price_bypassed boolean NOT NULL DEFAULT false, bypass_reason text, awarded_by uuid NOT NULL, awarded_at timestamptz NOT NULL DEFAULT now(), countersigned_by uuid, countersigned_at timestamptz, cancelled_at timestamptz, cancel_reason text, idempotency_key text UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), CHECK (NOT lowest_price_bypassed OR bypass_reason IS NOT NULL) );

CREATE TABLE IF NOT EXISTS public.partner_ledger_entries ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid NOT NULL REFERENCES public.partners(id) ON DELETE CASCADE, wallet_id uuid REFERENCES public.partner_wallets(id) ON DELETE SET NULL, order_id uuid REFERENCES public.mobility_orders(id) ON DELETE SET NULL, journey_id uuid REFERENCES public.journeys(id) ON DELETE SET NULL, settlement_id uuid, entry_kind public.partner_ledger_kind NOT NULL, direction public.ledger_direction NOT NULL, amount numeric(14,2) NOT NULL CHECK (amount >= 0), currency text NOT NULL DEFAULT 'KES', balance_after numeric(14,2), memo text, reference text, idempotency_key text UNIQUE, created_by uuid, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.partner_settlement_lines ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), settlement_id uuid NOT NULL REFERENCES public.partner_settlements(id) ON DELETE CASCADE, order_id uuid NOT NULL REFERENCES public.mobility_orders(id) ON DELETE CASCADE, partner_id uuid NOT NULL REFERENCES public.partners(id) ON DELETE CASCADE, customer_price numeric(14,2) NOT NULL DEFAULT 0, supplier_cost numeric(14,2) NOT NULL DEFAULT 0, yalla_margin numeric(14,2) NOT NULL DEFAULT 0, partner_margin numeric(14,2) NOT NULL DEFAULT 0, taxes numeric(14,2) NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT partner_settlement_lines_unique UNIQUE (settlement_id, order_id) );

CREATE TABLE IF NOT EXISTS public.payout_provider_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), disbursement_id uuid REFERENCES public.payout_disbursements(id) ON DELETE SET NULL, provider text NOT NULL DEFAULT 'MPESA_B2C', event_type text NOT NULL, provider_conversation_id text, provider_transaction_id text, result_code text, result_desc text, amount numeric(14,2), recipient text, transacted_at timestamptz, payload jsonb NOT NULL, payload_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (provider, payload_hash) );

CREATE TABLE IF NOT EXISTS public.freight_bookings ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_number text NOT NULL UNIQUE, award_id uuid NOT NULL UNIQUE REFERENCES public.freight_awards(id) ON DELETE RESTRICT, requirement_id uuid NOT NULL REFERENCES public.freight_requirements(id) ON DELETE CASCADE, carrier_id uuid NOT NULL REFERENCES public.carrier_profiles(id) ON DELETE RESTRICT, reservation_id uuid REFERENCES public.capacity_reservations(id) ON DELETE SET NULL, order_id uuid REFERENCES public.delivery_orders(id) ON DELETE SET NULL, route_id uuid REFERENCES public.logistics_routes(id) ON DELETE SET NULL, route_version_id uuid REFERENCES public.logistics_route_versions(id) ON DELETE SET NULL, manifest_id uuid REFERENCES public.logistics_manifests(id) ON DELETE SET NULL, dispatch_job_id uuid, vehicle_id uuid REFERENCES public.vehicles(id) ON DELETE SET NULL, driver_user_id uuid, state public.freight_booking_state NOT NULL DEFAULT 'CREATED', carrier_accepted_at timestamptz, carrier_declined_at timestamptz, carrier_decline_reason text, agreed_total numeric(14,2) NOT NULL CHECK (agreed_total >= 0), currency text NOT NULL DEFAULT 'KES', planned_pickup timestamptz, planned_delivery timestamptz, dispatched_at timestamptz, completed_at timestamptz, cancelled_at timestamptz, cancel_reason text, idempotency_key text UNIQUE, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.service_provider_claims ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), claim_ref text NOT NULL UNIQUE, carrier_id uuid NOT NULL REFERENCES public.carrier_profiles(id) ON DELETE RESTRICT, submitted_by uuid, destination_id uuid REFERENCES public.carrier_settlement_destinations(id) ON DELETE RESTRICT, order_id uuid, leg_id uuid NOT NULL, pod_submission_id uuid NOT NULL REFERENCES public.carrier_pod_submissions(id) ON DELETE RESTRICT, payable_line_id uuid REFERENCES public.carrier_payable_lines(id) ON DELETE SET NULL, sales_lead_id uuid REFERENCES public.sales_leads(id) ON DELETE SET NULL, sales_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, customer_label text, service_date date, origin_label text, destination_label text, service_description text NOT NULL, agreed_amount_kes numeric(14,2), claimed_amount_kes numeric(14,2) NOT NULL CHECK (claimed_amount_kes > 0), approved_amount_kes numeric(14,2), currency text NOT NULL DEFAULT 'KES', supporting_documents jsonb NOT NULL DEFAULT '[]'::jsonb, declaration_name text, declaration_accepted_at timestamptz, state text NOT NULL DEFAULT 'DRAFT', review_notes text, reviewed_by uuid, reviewed_at timestamptz, submitted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT spc_state_chk CHECK (state IN ('DRAFT','SUBMITTED','ADMIN_REVIEW','QUERY','APPROVED','INVOICED','PAYMENT_AUTHORISED','PAID','CLOSED','REJECTED')) );

CREATE TABLE IF NOT EXISTS public.freight_charges ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), charge_number text NOT NULL UNIQUE, party public.freight_charge_party NOT NULL, status public.freight_charge_status NOT NULL DEFAULT 'CALCULATED', customer_user_id uuid, corporate_account_id uuid, carrier_id uuid REFERENCES public.carrier_profiles(id), order_id uuid, package_id uuid REFERENCES public.packages(id), booking_id uuid REFERENCES public.freight_bookings(id), award_id uuid REFERENCES public.freight_awards(id), manifest_id uuid REFERENCES public.logistics_manifests(id), route_id uuid, stop_id uuid, quote_id uuid REFERENCES public.freight_quotes(id), rate_card_id uuid REFERENCES public.carrier_rate_cards(id), rate_line_id uuid REFERENCES public.carrier_rate_lines(id), charge_code text NOT NULL, basis public.freight_pricing_basis NOT NULL, quantity numeric(14,3) NOT NULL DEFAULT 1, unit_rate numeric(14,4) NOT NULL DEFAULT 0, amount numeric(14,2) NOT NULL DEFAULT 0, tax_amount numeric(14,2) NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'KES', commercial_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, operational_evidence jsonb NOT NULL DEFAULT '{}'::jsonb, reason_code text, correlation_id uuid NOT NULL DEFAULT gen_random_uuid(), request_id text, idempotency_key text NOT NULL UNIQUE, invoice_id uuid, settlement_id uuid, created_by uuid, approved_by uuid, approved_at timestamptz, voided_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.service_provider_invoices ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_ref text NOT NULL UNIQUE, claim_id uuid NOT NULL UNIQUE REFERENCES public.service_provider_claims(id) ON DELETE RESTRICT, carrier_id uuid NOT NULL REFERENCES public.carrier_profiles(id) ON DELETE RESTRICT, order_id uuid, leg_id uuid, pod_submission_id uuid NOT NULL, payable_line_id uuid, sales_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, amount_kes numeric(14,2) NOT NULL CHECK (amount_kes > 0), currency text NOT NULL DEFAULT 'KES', state text NOT NULL DEFAULT 'ISSUED', issued_by uuid, issued_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT spi_state_chk CHECK (state IN ('ISSUED','PAYMENT_AUTHORISED','PAID','CANCELLED')) );

CREATE TABLE IF NOT EXISTS public.freight_charge_adjustments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), charge_id uuid NOT NULL REFERENCES public.freight_charges(id), kind text NOT NULL CHECK (kind IN ('CREDIT','DEBIT','REVERSAL')), amount numeric(14,2) NOT NULL, currency text NOT NULL DEFAULT 'KES', reason_code text NOT NULL, reason_note text, requested_by uuid NOT NULL, approved_by uuid, approved_at timestamptz, status text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','APPROVED','REJECTED')), correlation_id uuid, idempotency_key text UNIQUE, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.freight_charge_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), charge_id uuid NOT NULL REFERENCES public.freight_charges(id) ON DELETE CASCADE, from_status public.freight_charge_status, to_status public.freight_charge_status NOT NULL, reason_code text, note text, actor_id uuid, actor_type text NOT NULL DEFAULT 'staff', correlation_id uuid, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );

CREATE TABLE IF NOT EXISTS public.freight_invoice_lines ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES public.freight_invoices(id) ON DELETE CASCADE, line_no integer NOT NULL, charge_id uuid NOT NULL REFERENCES public.freight_charges(id), description text NOT NULL, quantity numeric(14,3) NOT NULL DEFAULT 1, unit_rate numeric(14,4) NOT NULL DEFAULT 0, amount numeric(14,2) NOT NULL DEFAULT 0, tax_amount numeric(14,2) NOT NULL DEFAULT 0, lineage jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (invoice_id, line_no), UNIQUE (invoice_id, charge_id) );

CREATE TABLE IF NOT EXISTS public.freight_settlement_lines ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), settlement_id uuid NOT NULL REFERENCES public.freight_carrier_settlements(id) ON DELETE CASCADE, charge_id uuid REFERENCES public.freight_charges(id), booking_id uuid REFERENCES public.freight_bookings(id), description text NOT NULL, eligible_amount numeric(14,2) NOT NULL DEFAULT 0, adjustment_amount numeric(14,2) NOT NULL DEFAULT 0, net_amount numeric(14,2) NOT NULL DEFAULT 0, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (settlement_id, charge_id) );

CREATE TABLE IF NOT EXISTS public.service_provider_payments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_ref text NOT NULL UNIQUE, invoice_id uuid NOT NULL REFERENCES public.service_provider_invoices(id) ON DELETE RESTRICT, claim_id uuid NOT NULL REFERENCES public.service_provider_claims(id) ON DELETE RESTRICT, carrier_id uuid NOT NULL REFERENCES public.carrier_profiles(id) ON DELETE RESTRICT, destination_id uuid NOT NULL REFERENCES public.carrier_settlement_destinations(id) ON DELETE RESTRICT, msisdn_snapshot text NOT NULL, amount_kes numeric(14,2) NOT NULL CHECK (amount_kes > 0), currency text NOT NULL DEFAULT 'KES', method text NOT NULL DEFAULT 'MPESA', state text NOT NULL DEFAULT 'AUTHORISED', authorised_by uuid, authorised_at timestamptz NOT NULL DEFAULT now(), provider_reference text, provider_payload jsonb, paid_at timestamptz, recorded_by uuid, failure_reason text, idempotency_key text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT spp_state_chk CHECK (state IN ('AUTHORISED','PENDING_EXECUTION','PAID','FAILED')) );

CREATE TABLE IF NOT EXISTS public.freight_payment_allocations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid REFERENCES public.freight_invoices(id), invoice_line_id uuid REFERENCES public.freight_invoice_lines(id), payment_attempt_id uuid REFERENCES public.payment_attempts(id), mpesa_transaction_id uuid REFERENCES public.mpesa_transactions(id), provider text NOT NULL DEFAULT 'mpesa', provider_reference text, provider_status text, amount numeric(14,2) NOT NULL, currency text NOT NULL DEFAULT 'KES', state public.freight_alloc_state NOT NULL, unmatched_reason text, correlation_id uuid, request_id text, idempotency_key text NOT NULL UNIQUE, allocated_by uuid, reversed_at timestamptz, reversal_reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (payment_attempt_id IS NOT NULL OR mpesa_transaction_id IS NOT NULL OR provider_reference IS NOT NULL) );

CREATE TABLE IF NOT EXISTS public.service_provider_payment_receipts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), receipt_no text NOT NULL UNIQUE, payment_id uuid NOT NULL UNIQUE REFERENCES public.service_provider_payments(id) ON DELETE RESTRICT, verification_token text NOT NULL UNIQUE, integrity_hash text NOT NULL, document_version integer NOT NULL DEFAULT 1, issued_by uuid, issued_at timestamptz NOT NULL DEFAULT now() );

DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['mobility_orders','payout_disbursements','ride_payment_intents','settlement_failures','approval_payment_links','carrier_payable_lines','carrier_rate_lines','freight_awards','partner_ledger_entries','partner_settlement_lines','payout_provider_events','freight_bookings','service_provider_claims','freight_charges','service_provider_invoices','freight_charge_adjustments','freight_charge_events','freight_invoice_lines','freight_settlement_lines','service_provider_payments','freight_payment_allocations','service_provider_payment_receipts'] LOOP EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t); EXECUTE format('GRANT ALL ON public.%I TO service_role', t); EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('CREATE POLICY "Admins manage restored records" ON public.%I FOR ALL TO authenticated USING (public.has_any_role(auth.uid(), ARRAY[''admin'',''super_admin'',''finance_admin'']::public.app_role[])) WITH CHECK (public.has_any_role(auth.uid(), ARRAY[''admin'',''super_admin'',''finance_admin'']::public.app_role[]))', t); END LOOP; END $$;